                                        <p className="text-[rgba(255,255,255,0.5)] text-xs text-center py-4">No in-stock items in your cart</p>
                                    ) : inStockItems.map(item => {
                                        const price = item.price ?? 0;
                                        const lineTotal = price * item.quantity;
