                        ))}



                    </div>
                </div>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect, Suspense } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import Link from 'next/link';
import toast from 'react-hot-toast';
import { forgotPassword } from '@/lib/api';
import { ArrowLeft, Mail } from 'lucide-react';

function ForgotPasswordContent() {
    const router = useRouter();
    const searchParams = useSearchParams();
    const [loading, setLoading] = useState(false);
    const [email, setEmail] = useState('');
    const [submitted, setSubmitted] = useState(false);

    // Pre-fill email from ?email= query param (e.g. from security alert email)
    useEffect(() => {
        const prefill = searchParams.get('email');
        if (prefill) setEmail(decodeURIComponent(prefill));
    }, [searchParams]);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();

        if (!email) {
            toast.error('Please enter your email address');
            return;
        }

        setLoading(true);

        try {
            const result = await forgotPassword(email);
            if (result?.success) {
                setSubmitted(true);
            } else {
                toast.error(result?.error || result?.message || 'Something went wrong');
            }
        } catch (error) {
            console.error('Password reset request error:', error);
            toast.error('Server error. Please try again.');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="min-h-screen bg-cream flex flex-col items-center justify-center px-4 py-12">
            <div className="w-full max-w-md">

                <Link href="/login" className="inline-flex items-center gap-2 mb-8 text-sm font-medium text-warm-gray hover:text-burgundy transition-colors">
                    <ArrowLeft className="w-4 h-4" />
                    Back to login
                </Link>

                <div className="text-center mb-8">
                    <div className="w-16 h-16 mx-auto mb-6 rounded-full bg-burgundy/10 flex items-center justify-center">
                        <Mail className="w-8 h-8 text-burgundy" />
                    </div>
                    <h1 className="text-3xl font-bold text-charcoal">
                        Forgot Password
                    </h1>
                    <p className="mt-2 text-sm text-warm-gray">
                        {submitted
                            ? "Check your email for the reset link"
                            : "Enter your email and we'll send you a link to reset your password."}
                    </p>
                </div>

                {submitted ? (
                    <div className="rounded-2xl border border-light-border bg-white p-8 shadow-sm text-center">
                        <p className="text-sm text-charcoal mb-6">
                            We've sent an email to <strong className="font-semibold">{email}</strong> with a link to reset your password. It may take a few minutes to arrive.
                        </p>
                        <button
                            onClick={() => router.push('/login')}
                            className="w-full rounded-lg bg-charcoal py-3 text-sm font-semibold text-white transition-all hover:bg-gray-800"
                        >
                            Return to Login
                        </button>
                    </div>
                ) : (
                    <form
                        onSubmit={handleSubmit}
                        className="rounded-2xl border border-light-border bg-white p-8 shadow-sm"
                    >
                        <div className="mb-6">
                            <label className="block text-sm font-medium text-charcoal mb-1">
                                Email Address
                            </label>
                            <input
                                type="email"
                                value={email}
                                onChange={e => setEmail(e.target.value)}
                                className="w-full rounded-lg border border-light-border px-4 py-2.5 text-sm focus:border-burgundy focus:outline-none focus:ring-1 focus:ring-burgundy"
                                placeholder="you@example.com"
                                required
                            />
                        </div>

                        <button
                            type="submit"
                            disabled={loading || !email}
                            className="w-full rounded-lg bg-burgundy py-3 text-sm font-semibold text-white transition-all hover:bg-burgundy-dark disabled:opacity-50 disabled:cursor-not-allowed"
                        >
                            {loading ? 'Sending...' : 'Send Reset Link'}
                        </button>
                    </form>
                )}
            </div>
        </div>
    );
}

export default function ForgotPasswordPage() {
    return (
        <Suspense fallback={
            <div className="min-h-screen bg-cream flex items-center justify-center px-4">
                <div className="w-8 h-8 border-2 border-burgundy/30 border-t-burgundy rounded-full animate-spin" />
            </div>
        }>
            <ForgotPasswordContent />
        </Suspense>
    );
}

'use client';

import { useState, useEffect, Suspense } from 'react';
import { useParams, useSearchParams } from 'next/navigation';
import Link from 'next/link';
import { 
    Send, MessageSquare, Sparkles, AlertCircle, 
    ArrowRight, ChevronLeft, ShieldCheck, Mail, 
    User, HelpCircle, Bug, Activity, Leaf 
} from 'lucide-react';
import { submitFeedback } from '@/lib/api';
import { useAuth } from '@/context/AuthContext';
import toast from 'react-hot-toast';

const CATEGORIES = [
    { id: 'other', label: 'General Inquiry', icon: HelpCircle, color: '#A8B28B' },
    { id: 'complaint', label: 'Issue / Complaint', icon: Activity, color: '#B35A5A' },
    { id: 'suggestion', label: 'Improvement Suggestion', icon: Sparkles, color: '#D4A847' },
    { id: 'bug_report', label: 'Technical Bug Report', icon: Bug, color: '#36453A' },
    { id: 'contact', label: 'Collaborations', icon: Mail, color: '#4A5D23' },
];

function CustomerEnquiryContent() {
    const params = useParams();
    const searchParams = useSearchParams();
    const country = params?.country || 'in';
    const { user, isAuthenticated } = useAuth();
    const orderIdParam = searchParams?.get('orderId') || '';
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [submitted, setSubmitted] = useState(false);
    const [form, setForm] = useState({
        name: '',
        email: '',
        type: 'other',
        subject: '',
        message: ''
    });

    // Sync auth state and order ID to form
    useEffect(() => {
        if (isAuthenticated && user) {
            setForm(prev => ({
                ...prev,
                name: user.name || prev.name,
                email: user.email || prev.email
            }));
        }
    }, [isAuthenticated, user]);

    // Pre-fill form when orderId is provided
    useEffect(() => {
        if (orderIdParam) {
            setForm(prev => ({
                ...prev,
                type: 'complaint',
                subject: `Issue with Order #${orderIdParam.split('-')[0].toUpperCase()}`,
                message: `Hi, I need help with my order (ID: ${orderIdParam}).\n\nPlease describe your issue here...`
            }));
        }
    }, [orderIdParam]);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!form.message.trim() || !form.subject.trim()) {
            toast.error('Please fill in both subject and message.');
            return;
        }

        setIsSubmitting(true);
        try {
            const res = await submitFeedback({
                name: form.name,
                email: form.email,
                type: form.type,
                subject: form.subject,
                message: form.message
            });

            if (res.success) {
                toast.success('Your enquiry has been received.');
                setSubmitted(true);
            } else {
                toast.error(res.message || 'Failed to submit enquiry.');
            }
        } catch {
            toast.error('A network error occurred. Please try again.');
        } finally {
            setIsSubmitting(false);
        }
    };

    if (submitted) {
        return (
            <div className="min-h-screen bg-[#FDFBF7] flex items-center justify-center p-6">
                <div className="max-w-xl w-full text-center bg-white rounded-[40px] border border-[#4A5D23]/10 p-12 shadow-2xl animate-in zoom-in-95 duration-500">
                    <div className="w-24 h-24 rounded-full bg-[#4A5D23]/10 flex items-center justify-center mx-auto mb-8 shadow-inner overflow-hidden relative">
                        <Leaf className="h-12 w-12 text-[#4A5D23] animate-bounce" />
                        <div className="absolute inset-0 bg-gradient-to-t from-[#4A5D23]/5 to-transparent"></div>
                    </div>
                    <h2 className="text-3xl md:text-4xl font-bold text-[#1a2408] mb-6">Enquiry Received</h2>
                    <p className="text-[#5B4A31] text-lg mb-10 leading-relaxed font-medium">
                        Thank you for reaching out. Your enquiry has been registered in our harmony system. 
                        Our team will review it and respond shortly.
                    </p>
                    <div className="flex flex-col sm:flex-row gap-4 justify-center">
                        <Link 
                            href={`/${country}/help-center`} 
                            className="inline-flex items-center justify-center gap-2 px-8 py-4 rounded-2xl bg-[#4A5D23] text-white font-bold hover:bg-[#3a491b] transition-all shadow-xl hover:-translate-y-1"
                        >
                            Back to Help Center
                        </Link>
                        {isAuthenticated && (
                            <Link 
                                href={`/${country}/account/support`} 
                                className="inline-flex items-center justify-center gap-2 px-8 py-4 rounded-2xl bg-white border border-[#4A5D23]/20 text-[#4A5D23] font-bold hover:bg-[#4A5D23]/5 transition-all shadow-sm"
                            >
                                Track in My Account <ArrowRight className="h-4 w-4" />
                            </Link>
                        )}
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-[#FDFBF7]">
            {/* Header section */}
            <section className="relative py-20 px-6 overflow-hidden">
                <div 
                    className="absolute inset-0 z-0 opacity-30 bg-repeat bg-center"
                    style={{ 
                        backgroundImage: "url('/ayurvedic-texture.png')",
                        backgroundSize: '400px',
                        filter: 'sepia(0.2)'
                    }}
                ></div>
                <div className="absolute bottom-0 left-0 w-full h-24 bg-gradient-to-t from-[#FDFBF7] to-transparent z-0"></div>
                
                <div className="max-w-4xl mx-auto text-center relative z-10">
                    <Link 
                        href={`/${country}/help-center`} 
                        className="inline-flex items-center gap-2 text-[#4A5D23] font-bold text-sm uppercase tracking-widest mb-8 hover:gap-3 transition-all"
                    >
                        <ChevronLeft className="h-4 w-4" /> Help Center
                    </Link>
                    <h1 className="text-4xl md:text-6xl font-bold text-[#1a2408] mb-6 tracking-tight">
                        Customer <span className="text-[#4A5D23]">Enquiry</span>
                    </h1>
                    <p className="text-[#5B4A31] text-lg max-w-2xl mx-auto font-medium leading-relaxed">
                        Share your thoughts, report an issue, or suggest an improvement. 
                        Our heart and ears are open to your Vedic journey.
                    </p>
                </div>
            </section>

            <main className="max-w-5xl mx-auto px-6 pb-24 relative z-10">
                <div className="grid grid-cols-1 lg:grid-cols-[1fr_320px] gap-12">
                    
                    {/* Left: Form Area */}
                    <div className="bg-white rounded-[40px] border border-[#4A5D23]/10 shadow-2xl p-8 md:p-12">
                        <form onSubmit={handleSubmit} className="space-y-8">
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                                <div className="space-y-3">
                                    <label className="text-xs font-black text-[#1a2408] uppercase tracking-[0.2em] ml-1 flex items-center gap-2">
                                        <User className="h-3 w-3 text-[#4A5D23]" /> Full Name
                                    </label>
                                    <input 
                                        type="text"
                                        value={form.name}
                                        onChange={e => setForm({...form, name: e.target.value})}
                                        placeholder="Enter your name"
                                        required
                                        className="w-full px-6 py-4 rounded-2xl bg-gray-50/50 border border-transparent focus:bg-white focus:border-[#4A5D23]/30 focus:outline-none focus:ring-4 focus:ring-[#4A5D23]/5 transition-all font-medium text-gray-900"
                                    />
                                </div>
                                <div className="space-y-3">
                                    <label className="text-xs font-black text-[#1a2408] uppercase tracking-[0.2em] ml-1 flex items-center gap-2">
                                        <Mail className="h-3 w-3 text-[#4A5D23]" /> Email Address
                                    </label>
                                    <input 
                                        type="email"
                                        value={form.email}
                                        onChange={e => setForm({...form, email: e.target.value})}
                                        placeholder="Enter your contact email"
                                        required
                                        className="w-full px-6 py-4 rounded-2xl bg-gray-50/50 border border-transparent focus:bg-white focus:border-[#4A5D23]/30 focus:outline-none focus:ring-4 focus:ring-[#4A5D23]/5 transition-all font-medium text-gray-900"
                                    />
                                </div>
                            </div>

                            <div className="space-y-4">
                                <label className="text-xs font-black text-[#1a2408] uppercase tracking-[0.2em] ml-1">Enquiry Category</label>
                                <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-3">
                                    {CATEGORIES.map(cat => {
                                        const Icon = cat.icon;
                                        const isActive = form.type === cat.id;
                                        return (
                                            <button
                                                key={cat.id}
                                                type="button"
                                                onClick={() => setForm({...form, type: cat.id})}
                                                className={`flex flex-col items-center justify-center p-4 rounded-3xl border transition-all ${
                                                    isActive 
                                                    ? 'bg-[#4A5D23] border-[#4A5D23] shadow-lg -translate-y-1' 
                                                    : 'bg-white border-gray-100 hover:border-[#4A5D23]/30 hover:bg-[#FDFBF7]'
                                                }`}
                                            >
                                                <Icon className={`h-6 w-6 mb-2 ${isActive ? 'text-white' : 'text-[#4A5D23]'}`} />
                                                <span className={`text-[10px] font-black uppercase tracking-wider text-center ${isActive ? 'text-white' : 'text-[#1a2408]'}`}>
                                                    {cat.label.split(' ')[0]}
                                                </span>
                                            </button>
                                        );
                                    })}
                                </div>
                            </div>

                            <div className="space-y-3">
                                <label className="text-xs font-black text-[#1a2408] uppercase tracking-[0.2em] ml-1 flex items-center gap-2">
                                    <MessageSquare className="h-3 w-3 text-[#4A5D23]" /> Subject
                                </label>
                                <input 
                                    type="text"
                                    value={form.subject}
                                    onChange={e => setForm({...form, subject: e.target.value})}
                                    placeholder="Briefly describe your enquiry"
                                    required
                                    className="w-full px-6 py-4 rounded-2xl bg-gray-50/50 border border-transparent focus:bg-white focus:border-[#4A5D23]/30 focus:outline-none focus:ring-4 focus:ring-[#4A5D23]/5 transition-all font-medium text-gray-900"
                                />
                            </div>

                            <div className="space-y-3">
                                <label className="text-xs font-black text-[#1a2408] uppercase tracking-[0.2em] ml-1 flex items-center gap-2">
                                    <Send className="h-3 w-3 text-[#4A5D23]" /> Message Details
                                </label>
                                <textarea 
                                    value={form.message}
                                    onChange={e => setForm({...form, message: e.target.value})}
                                    placeholder="Provide more context or details here..."
                                    required
                                    rows={6}
                                    className="w-full px-6 py-6 rounded-[32px] bg-gray-50/50 border border-transparent focus:bg-white focus:border-[#4A5D23]/30 focus:outline-none focus:ring-4 focus:ring-[#4A5D23]/5 transition-all font-medium text-gray-900 resize-none leading-relaxed"
                                />
                            </div>

                            <div className="pt-6 border-t border-gray-100 flex flex-col sm:flex-row items-center justify-between gap-8">
                                <button
                                    type="submit"
                                    disabled={isSubmitting}
                                    className="w-full sm:w-auto inline-flex items-center justify-center gap-3 bg-[#1a2408] text-white px-12 py-5 rounded-2xl font-black text-lg hover:bg-[#4A5D23] transition-all disabled:opacity-50 cursor-pointer shadow-xl hover:-translate-y-1 group"
                                >
                                    {isSubmitting ? 'Submitting...' : 'Send Enquiry'}
                                    <Send className={`h-6 w-6 transition-transform group-hover:translate-x-1 group-hover:-translate-y-1 ${isSubmitting ? 'animate-pulse' : ''}`} />
                                </button>
                                <div className="flex items-center gap-3 text-sm font-bold text-[#5B4A31]/60">
                                    <ShieldCheck className="h-5 w-5 text-[#4A5D23]" />
                                    <span>Encrypted & Private</span>
                                </div>
                            </div>
                        </form>
                    </div>

                    {/* Right: Info Sidebar */}
                    <div className="space-y-8">
                        <div className="bg-[#4A5D23]/5 rounded-[32px] p-8 border border-[#4A5D23]/10">
                            <h3 className="text-xl font-bold text-[#1a2408] mb-6">Support Guidance</h3>
                            <div className="space-y-6">
                                <div className="flex gap-4">
                                    <div className="w-10 h-10 rounded-xl bg-white flex items-center justify-center flex-shrink-0 shadow-sm">
                                        <Leaf className="h-5 w-5 text-[#4A5D23]" />
                                    </div>
                                    <div>
                                        <h4 className="text-xs font-black uppercase text-[#1a2408] mb-1">Response Time</h4>
                                        <p className="text-xs text-[#5B4A31] leading-relaxed">Most enquiries are addressed within 24 to 48 business hours.</p>
                                    </div>
                                </div>
                                <div className="flex gap-4">
                                    <div className="w-10 h-10 rounded-xl bg-white flex items-center justify-center flex-shrink-0 shadow-sm">
                                        <HelpCircle className="h-5 w-5 text-[#4A5D23]" />
                                    </div>
                                    <div>
                                        <h4 className="text-xs font-black uppercase text-[#1a2408] mb-1">Check FAQs</h4>
                                        <p className="text-xs text-[#5B4A31] leading-relaxed">Your question might already have an <Link href={`/${country}/help-center/faq`} className="text-[#4A5D23] underline font-bold">answer here</Link>.</p>
                                    </div>
                                </div>
                                <div className="flex gap-4">
                                    <div className="w-10 h-10 rounded-xl bg-white flex items-center justify-center flex-shrink-0 shadow-sm">
                                        <ShieldCheck className="h-5 w-5 text-[#4A5D23]" />
                                    </div>
                                    <div>
                                        <h4 className="text-xs font-black uppercase text-[#1a2408] mb-1">Order Issues</h4>
                                        <p className="text-xs text-[#5B4A31] leading-relaxed">For specific orders, use our <Link href={`/${country}/help-center/support`} className="text-[#4A5D23] underline font-bold">Ticket System</Link>.</p>
                                    </div>
                                </div>
                            </div>
                        </div>

                        <div className="bg-[#1a2408] rounded-[32px] p-8 text-white relative overflow-hidden group">
                            <div className="relative z-10">
                                <h3 className="text-lg font-bold text-[#D4A847] mb-4">Are you a member?</h3>
                                <p className="text-xs text-white/70 mb-6 leading-relaxed">
                                    Logged-in users can track their enquiries and view replies directly from their dashboard.
                                </p>
                                {!isAuthenticated ? (
                                    <Link 
                                        href={`/${country}/login`} 
                                        className="inline-flex items-center gap-2 text-xs font-black uppercase bg-white text-[#1a2408] px-6 py-3 rounded-xl hover:bg-[#F2E8CF] transition-all"
                                    >
                                        Log In Now <ArrowRight className="h-3.5 w-3.5" />
                                    </Link>
                                ) : (
                                    <Link 
                                        href={`/${country}/account/support`} 
                                        className="inline-flex items-center gap-2 text-xs font-black uppercase bg-[#4A5D23] text-white px-6 py-3 rounded-xl hover:bg-[#3a491b] transition-all"
                                    >
                                        View My Dashboard <ArrowRight className="h-3.5 w-3.5" />
                                    </Link>
                                )}
                            </div>
                            <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:scale-125 transition-transform duration-700">
                                <Sparkles className="h-16 w-16" />
                            </div>
                        </div>
                    </div>

                </div>

                <div className="mt-20 text-center">
                    <p className="text-sm font-bold text-[#5B4A31]/40 uppercase tracking-widest mb-6 flex items-center justify-center gap-3">
                        <span className="h-px w-8 bg-current"></span>
                        Vedic Support Ethics
                        <span className="h-px w-8 bg-current"></span>
                    </p>
                    <div className="max-w-3xl mx-auto p-10 rounded-[40px] border border-dashed border-[#4A5D23]/20">
                        <p className="italic text-[#5B4A31] text-lg font-medium leading-relaxed">
                            "Every enquiry is a seed of trust. At Vedashi, we nurture this seed with transparency, 
                            mindfulness, and a commitment to your holistic wellbeing."
                        </p>
                    </div>
                </div>
            </main>
        </div>
    );
}

export default function CustomerEnquiryPage() {
    return (
        <Suspense fallback={
            <div className="min-h-screen bg-[#FDFBF7] flex items-center justify-center">
                <Leaf className="h-8 w-8 animate-spin text-[#4A5D23]" />
            </div>
        }>
            <CustomerEnquiryContent />
        </Suspense>
    );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import Link from 'next/link';
import {
    Search, ChevronDown, ChevronLeft, HelpCircle,
    CreditCard, Truck, Leaf, ShieldCheck, Clock,
    Mail, ArrowUpRight, BookOpen, FileText, Sparkles
} from 'lucide-react';
import { getFaqs, searchFaqs } from '@/lib/api';
import { generateFAQPageJsonLd } from '@/lib/seo';

interface Faq {
    faq_id: string;
    question: string;
    answer: string;
    category: string;
    sort_order?: number;
    is_active?: boolean;
}

/* ── Category icon mapping ─────────────────────────────────── */
const CATEGORY_ICONS: Record<string, React.ElementType> = {
    'Account & Billing': CreditCard,
    'Orders & Shipping': Truck,
    'Products & Ingredients': Leaf,
    'Returns & Refunds': ShieldCheck,
    'General': HelpCircle,
};

function getCategoryIcon(category: string) {
    return CATEGORY_ICONS[category] || HelpCircle;
}

export default function FAQPage() {
    const [faqData, setFaqData] = useState<{ faqs: Faq[]; grouped: Record<string, Faq[]> }>({ faqs: [], grouped: {} });
    const [searchQuery, setSearchQuery] = useState('');
    const [searchResults, setSearchResults] = useState<Faq[] | null>(null);
    const [expandedId, setExpandedId] = useState<string | null>(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        getFaqs().then((data) => {
            setFaqData(data || { faqs: [], grouped: {} });
            setLoading(false);
        });
    }, []);

    const handleSearch = useCallback(async () => {
        if (!searchQuery.trim()) {
            setSearchResults(null);
            return;
        }
        const results = await searchFaqs(searchQuery);
        setSearchResults(Array.isArray(results) ? results : []);
    }, [searchQuery]);

    const categories = Object.keys(faqData.grouped || {});

    return (
        <div className="min-h-screen bg-[#FDFBF7]">
            {/* Structured Data */}
            {!loading && faqData.faqs.length > 0 && (
                <script
                    type="application/ld+json"
                    dangerouslySetInnerHTML={{ __html: JSON.stringify(generateFAQPageJsonLd(faqData.faqs)) }}
                />
            )}

            {/* ═══════════════ HERO SECTION ═══════════════ */}
            <section className="relative overflow-hidden py-20 px-6">
                {/* Ayurvedic Texture Background */}
                <div 
                    className="absolute inset-0 z-0 opacity-40 bg-repeat bg-center"
                    style={{ 
                        backgroundImage: "url('/ayurvedic-texture.png')",
                        backgroundSize: '400px',
                        filter: 'sepia(0.1) contrast(1.05)'
                    }}
                ></div>

                {/* Decorative botanical SVG background */}
                <div className="absolute inset-0 opacity-[0.1] pointer-events-none">
                    <svg className="absolute top-0 right-0 h-full w-1/2" viewBox="0 0 400 500" fill="none">
                        <path d="M250 50 C300 100, 350 200, 300 300 C250 400, 150 450, 100 400 C50 350, 80 250, 150 200 C220 150, 200 0, 250 50Z" stroke="#4A5D23" strokeWidth="1.5" fill="none" />
                    </svg>
                </div>

                <div className="max-w-4xl mx-auto text-center relative z-10">
                    <div className="inline-flex items-center gap-2 bg-[#4A5D23]/10 backdrop-blur-sm border border-[#4A5D23]/10 rounded-full px-5 py-2 mb-6 shadow-sm">
                        <Sparkles className="h-4 w-4 text-[#4A5D23]" />
                        <span className="text-xs font-bold tracking-[0.2em] uppercase text-[#2D3A15]">Knowledge Base</span>
                    </div>

                    <h1 className="text-4xl md:text-6xl font-bold text-[#1a2408] mb-6 leading-tight">
                        How can we help you <em className="not-italic text-[#4A5D23]">grow</em>?
                    </h1>

                    {/* Search bar */}
                    <div className="relative max-w-2xl mx-auto mt-10 group">
                        <div className="absolute -inset-1 bg-gradient-to-r from-[#4A5D23]/20 to-[#8B4513]/20 rounded-2xl blur opacity-25 group-hover:opacity-40 transition duration-1000"></div>
                        <input
                            type="text"
                            value={searchQuery}
                            onChange={(e) => {
                                setSearchQuery(e.target.value);
                                if (!e.target.value.trim()) setSearchResults(null);
                            }}
                            onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
                            placeholder="Search for tracking, returns, or ingredients..."
                            className="relative w-full pl-14 pr-4 py-5 rounded-2xl bg-white/90 backdrop-blur-sm text-gray-900 placeholder-gray-400 text-lg border border-[#4A5D23]/10 focus:outline-none focus:ring-2 focus:ring-[#4A5D23] shadow-2xl transition-all"
                        />
                        <Search className="absolute left-5 top-1/2 -translate-y-1/2 h-6 w-6 text-[#4A5D23]" />
                    </div>
                </div>
            </section>

            {/* ═══════════════ MAIN CONTENT ═══════════════ */}
            <div className="max-w-7xl mx-auto px-6 py-12 md:py-20">

                {/* Search results banner */}
                {searchResults && (
                    <div className="mb-12">
                        <div className="flex items-center justify-between mb-6 pb-4 border-b border-[#4A5D23]/10">
                            <h2 className="text-2xl font-bold text-[#1a2408] flex items-center gap-3">
                                <div className="w-1.5 h-8 bg-[#4A5D23] rounded-full"></div>
                                {searchResults.length > 0
                                    ? `${searchResults.length} result${searchResults.length !== 1 ? 's' : ''} for "${searchQuery}"`
                                    : 'No results found'}
                            </h2>
                            <button
                                onClick={() => { setSearchQuery(''); setSearchResults(null); }}
                                className="px-4 py-2 rounded-xl bg-[#4A5D23]/5 text-[#4A5D23] hover:bg-[#4A5D23] hover:text-white font-bold text-sm transition-all shadow-sm"
                            >
                                Clear search
                            </button>
                        </div>
                        {searchResults.length > 0 ? (
                            <div className="grid gap-4 mb-12">
                                {searchResults.map((faq: Faq) => (
                                    <div
                                        key={faq.faq_id}
                                        className="bg-white rounded-2xl border border-[#4A5D23]/5 overflow-hidden transition-all hover:border-[#4A5D23]/20 hover:shadow-xl group"
                                    >
                                        <button
                                            onClick={() => setExpandedId(expandedId === faq.faq_id ? null : faq.faq_id)}
                                            className="w-full flex items-center justify-between p-6 text-left cursor-pointer"
                                        >
                                            <span className="text-lg font-bold text-[#1a2408] pr-6 group-hover:text-[#4A5D23] transition-colors">{faq.question}</span>
                                            <div className={`p-2 rounded-lg bg-gray-50 group-hover:bg-[#4A5D23]/10 transition-colors ${expandedId === faq.faq_id ? 'bg-[#4A5D23] text-white' : 'text-[#4A5D23]'}`}>
                                                <ChevronDown
                                                    className={`h-5 w-5 transition-transform duration-300 ${expandedId === faq.faq_id ? 'rotate-180 text-white' : ''}`}
                                                />
                                            </div>
                                        </button>
                                        <div className={`overflow-hidden transition-all duration-300 ${expandedId === faq.faq_id ? 'max-h-[800px] border-t border-gray-50' : 'max-h-0'}`}>
                                            <div className="p-6 text-base text-[#5B4A31] leading-relaxed whitespace-pre-line bg-gray-50/30">
                                                {faq.answer}
                                            </div>
                                            <div className="px-6 pb-6">
                                                <span className="text-[10px] uppercase tracking-widest font-black px-3 py-1 rounded-full bg-[#4A5D23]/10 text-[#4A5D23]">
                                                    {faq.category}
                                                </span>
                                            </div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        ) : (
                            <div className="text-center py-20 bg-white rounded-3xl border border-[#4A5D23]/5">
                                <Search className="h-16 w-16 text-gray-200 mx-auto mb-6" />
                                <h3 className="text-2xl font-bold text-[#1a2408] mb-2">No matching questions</h3>
                                <p className="text-[#5B4A31]">Try a different search term or browse our categories below.</p>
                            </div>
                        )}
                    </div>
                )}

                <div className="flex flex-col lg:flex-row gap-16">
                    {/* ─── LEFT COLUMN: FAQ Accordions ─── */}
                    <div className="flex-1 min-w-0">
                        <div className="mb-12">
                            <h2 className="text-3xl md:text-5xl font-bold text-[#1a2408] mb-4">
                                Frequently Asked Questions
                            </h2>
                            <p className="text-lg text-[#5B4A31] max-w-2xl leading-relaxed">
                                Curated answers for our most common inquiries, rooted in clarity and convenience.
                            </p>
                        </div>

                        {loading ? (
                            /* Loading skeleton */
                            <div className="space-y-12">
                                {[...Array(3)].map((_, i) => (
                                    <div key={i}>
                                        <div className="flex items-center gap-3 mb-6">
                                            <div className="h-10 w-10 bg-gray-200 rounded-xl animate-pulse" />
                                            <div className="h-8 bg-gray-200 rounded-full w-48 animate-pulse" />
                                        </div>
                                        <div className="space-y-4">
                                            {[...Array(2)].map((_, j) => (
                                                <div key={j} className="bg-white rounded-2xl p-8 border border-gray-100 animate-pulse">
                                                    <div className="h-6 bg-gray-200 rounded-full w-3/4" />
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                ))}
                            </div>
                        ) : categories.length === 0 && faqData.faqs.length === 0 ? (
                            /* Empty state */
                            <div className="text-center py-24 bg-white rounded-[40px] border border-[#4A5D23]/5">
                                <HelpCircle className="h-20 w-20 text-gray-100 mx-auto mb-6" />
                                <h3 className="text-2xl font-bold text-[#1a2408] mb-2">No FAQs available</h3>
                                <p className="text-[#5B4A31]">Please check back later as we grow our knowledge base.</p>
                            </div>
                        ) : !searchResults && (
                            /* Category-grouped FAQ sections */
                            <div className="space-y-16">
                                {(categories.length > 0 ? categories : ['General']).map((category) => {
                                    const Icon = getCategoryIcon(category);
                                    const faqs = categories.length > 0
                                        ? (faqData.grouped?.[category] || [])
                                        : faqData.faqs || [];

                                    if (faqs.length === 0) return null;

                                    return (
                                        <div key={category} className="faq-category-group">
                                            {/* Category header */}
                                            <div className="flex items-center gap-4 mb-8">
                                                <div className="w-12 h-12 rounded-2xl bg-[#4A5D23]/10 flex items-center justify-center shadow-inner">
                                                    <Icon className="h-6 w-6 text-[#4A5D23]" />
                                                </div>
                                                <h3 className="text-2xl font-bold text-[#1a2408] tracking-tight">{category}</h3>
                                            </div>

                                            {/* FAQ items */}
                                            <div className="grid gap-4">
                                                {faqs.map((faq: Faq) => {
                                                    const isExpanded = expandedId === faq.faq_id;
                                                    return (
                                                        <div
                                                            key={faq.faq_id}
                                                            className={`bg-white rounded-3xl border transition-all duration-500 overflow-hidden ${isExpanded
                                                                ? 'border-[#4A5D23]/30 shadow-2xl scale-[1.01]'
                                                                : 'border-[#4A5D23]/5 hover:border-[#4A5D23]/15 hover:shadow-lg'
                                                                }`}
                                                        >
                                                            <button
                                                                onClick={() => setExpandedId(isExpanded ? null : faq.faq_id)}
                                                                className="w-full flex items-center justify-between p-7 text-left cursor-pointer group"
                                                            >
                                                                <span className="text-lg font-bold text-[#1a2408] pr-8 group-hover:text-[#4A5D23] transition-colors leading-snug">
                                                                    {faq.question}
                                                                </span>
                                                                <div className={`p-2.5 rounded-xl transition-all duration-300 ${isExpanded ? 'bg-[#4A5D23] text-white' : 'bg-[#4A5D23]/5 text-[#4A5D23] group-hover:bg-[#4A5D23]/10'}`}>
                                                                    <ChevronDown
                                                                        className={`h-5 w-5 transition-transform duration-500 ${isExpanded ? 'rotate-180' : ''}`}
                                                                    />
                                                                </div>
                                                            </button>
                                                            <div
                                                                className={`overflow-hidden transition-all duration-500 ease-in-out ${isExpanded ? 'max-h-[1000px] border-t border-gray-50' : 'max-h-0'}`}
                                                            >
                                                                <div className="p-8 text-lg text-[#5B4A31] leading-relaxed whitespace-pre-line bg-gray-50/30">
                                                                    {faq.answer}
                                                                </div>
                                                            </div>
                                                        </div>
                                                    );
                                                })}
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>
                        )}
                    </div>

                    {/* ─── RIGHT COLUMN: Sidebar ─── */}
                    <div className="w-full lg:w-[380px] flex-shrink-0">
                        <div className="lg:sticky lg:top-8 space-y-10">

                            {/* Featured: Our Organic Promise */}
                            <div className="relative group bg-[#1a2408] rounded-[40px] p-10 overflow-hidden shadow-2xl">
                                <div className="absolute inset-0 bg-[url('/ayurvedic-texture.png')] opacity-10 bg-repeat pointer-events-none"></div>
                                <div className="relative z-10">
                                    <div className="flex items-start justify-between mb-8">
                                        <div className="flex items-center gap-3">
                                            <div className="w-10 h-10 rounded-full bg-[#4A5D23] flex items-center justify-center shadow-lg">
                                                <ShieldCheck className="h-5 w-5 text-white" />
                                            </div>
