                </div>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import Link from 'next/link';
import { useParams } from 'next/navigation';
import { ChevronLeft, BookOpen, Eye, Clock, ChevronRight } from 'lucide-react';
import { getKBArticle } from '@/lib/api';

export default function KBArticlePage() {
    const params = useParams();
    const slug = params.slug as string;
    const [data, setData] = useState<any>(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        if (slug) {
            getKBArticle(slug).then((d) => { setData(d); setLoading(false); });
        }
    }, [slug]);

    if (loading) {
        return (
            <div className="min-h-screen bg-[#FDFBF7]">
                <div className="max-w-4xl mx-auto px-6 py-20">
                    <div className="animate-pulse space-y-8">
                        <div className="h-10 bg-gray-100 rounded-2xl w-3/4"></div>
                        <div className="h-4 bg-gray-50 rounded-full w-1/4"></div>
                        <div className="space-y-6 mt-12 bg-white rounded-[40px] p-10 border border-[#4A5D23]/5">
                            {[...Array(12)].map((_, i) => <div key={i} className={`h-4 bg-gray-50 rounded-full ${i % 3 === 0 ? 'w-full' : i % 3 === 1 ? 'w-5/6' : 'w-2/3'}`}></div>)}
                        </div>
                    </div>
                </div>
            </div>
        );
    }

    if (!data?.article) {
        return (
            <div className="min-h-screen bg-[#FDFBF7] flex items-center justify-center p-6">
                <div className="text-center bg-white rounded-[60px] p-16 border border-[#4A5D23]/5 shadow-2xl max-w-lg w-full">
                    <div className="w-24 h-24 rounded-[30px] bg-[#4A5D23]/10 flex items-center justify-center mx-auto mb-10">
                        <BookOpen className="h-10 w-10 text-[#4A5D23]" />
                    </div>
                    <h2 className="text-3xl font-bold text-[#1a2408] mb-4">Ancient Scroll Not Found</h2>
                    <p className="text-[#5B4A31] mb-10 font-medium">This search did not lead us to the wisdom you seek.</p>
                    <Link href="/help-center/knowledge-base" className="inline-flex items-center gap-3 bg-[#4A5D23] text-white px-10 py-5 rounded-[20px] font-black uppercase tracking-widest text-sm hover:bg-[#3a491b] transition-all shadow-xl">
                        <ChevronLeft className="h-5 w-5" /> Return to Archives
                    </Link>
                </div>
            </div>
        );
    }

    const { article, related } = data;

    return (
        <div className="min-h-screen bg-[#FDFBF7]">
            {/* ═══════════════ ARTICLE HEADER ═══════════════ */}
            <section className="relative overflow-hidden py-24 px-6 border-b border-[#4A5D23]/10">
                {/* Ayurvedic Texture Background (Subtle) */}
                <div 
                    className="absolute inset-0 z-0 opacity-20 bg-repeat bg-center"
                    style={{ 
                        backgroundImage: "url('/ayurvedic-texture.png')",
                        backgroundSize: '400px',
                        filter: 'sepia(0.2) contrast(1.1)'
                    }}
                ></div>
                
                <div className="max-w-4xl mx-auto relative z-10">
                    <Link href="/help-center/knowledge-base" className="inline-flex items-center gap-3 text-[#4A5D23] text-sm font-black uppercase tracking-widest mb-10 hover:text-[#3a491b] transition-all group">
                        <div className="w-10 h-10 rounded-xl bg-white shadow-md flex items-center justify-center group-hover:bg-[#4A5D23] group-hover:text-white transition-all">
                            <ChevronLeft className="h-5 w-5" />
                        </div>
                        Back to Knowledge Hub
                    </Link>
                    
                    <h1 className="text-4xl md:text-6xl font-bold text-[#1a2408] mb-8 leading-tight">
                        {article.title}
                    </h1>
                    
                    <div className="flex flex-wrap items-center gap-8 text-xs font-black uppercase tracking-[0.2em]">
                        {article.category_name && (
                            <span className="bg-[#4A5D23] text-white px-5 py-2 rounded-full shadow-lg shadow-[#4A5D23]/20">
                                {article.category_name}
                            </span>
                        )}
                        <span className="flex items-center gap-2 text-[#5B4A31]/60">
                            <Eye className="h-4 w-4" />
                            {article.view_count} ENLIGHTENED
                        </span>
                        <span className="flex items-center gap-2 text-[#5B4A31]/60">
                            <Clock className="h-4 w-4" />
                            UPDATED {new Date(article.updated_at || article.created_at).toLocaleDateString()}
                        </span>
                    </div>
                </div>
            </section>

            <div className="max-w-4xl mx-auto px-6 py-16">
                <article className="bg-white rounded-[60px] p-12 md:p-20 border border-[#4A5D23]/5 shadow-[0_32px_64px_-16px_rgba(74,93,35,0.08)]">
                    <div
                        className="prose prose-lg max-w-none prose-headings:prose-headings:text-[#1a2408] prose-p:text-[#5B4A31] prose-p:leading-relaxed prose-a:text-[#4A5D23] prose-strong:text-[#1a2408] prose-img:rounded-[30px] prose-img:shadow-2xl"
                        dangerouslySetInnerHTML={{ __html: article.content.replace(/\n/g, '<br/>') }}
                    />
                </article>

                {/* Related Articles */}
                {related && related.length > 0 && (
                    <div className="mt-20">
                        <div className="flex items-center gap-4 mb-8">
                            <h3 className="text-3xl font-bold text-[#1a2408]">Related Wisdom</h3>
                            <div className="flex-1 h-px bg-[#4A5D23]/10"></div>
                        </div>
                        <div className="grid gap-6 md:grid-cols-2">
                            {related.map((r: any) => (
                                <Link
                                    key={r.article_id}
                                    href={`/help-center/knowledge-base/${r.slug}`}
                                    className="group bg-white rounded-[32px] p-8 border border-[#4A5D23]/5 hover:border-[#4A5D23]/20 hover:shadow-xl transition-all flex items-center justify-between"
                                >
                                    <div className="flex-1">
                                        <h4 className="text-lg font-bold text-[#1a2408] group-hover:text-[#4A5D23] transition-colors mb-2">
                                            {r.title}
                                        </h4>
                                        {r.excerpt && <p className="text-sm text-[#5B4A31]/60 line-clamp-1 font-medium italic">{r.excerpt}</p>}
                                    </div>
                                    <div className="w-10 h-10 rounded-xl bg-gray-50 flex items-center justify-center text-gray-400 group-hover:bg-[#4A5D23] group-hover:text-white transition-all ml-4 shrink-0">
                                        <ChevronRight className="h-5 w-5" />
                                    </div>
                                </Link>
                            ))}
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import Link from 'next/link';
import {
    Search, ChevronLeft, ChevronDown, BookOpen,
    ShoppingCart, HeadphonesIcon, Truck, Sparkles,
    ArrowRight, Clock, Leaf, HelpCircle, FileText
} from 'lucide-react';
import { getKBCategories, getKBArticles, searchKBArticles } from '@/lib/api';

/* ── Category icon mapping ─────────────────────────────────── */
const CATEGORY_ICONS: Record<string, React.ElementType> = {
    'Shopping': ShoppingCart,
    'Customer Care': HeadphonesIcon,
    'Logistics': Truck,
    'Products': Leaf,
    'General': FileText,
};

function getCategoryIcon(category: string) {
    if (!category) return FileText;
    for (const [key, icon] of Object.entries(CATEGORY_ICONS)) {
        if (category.toLowerCase().includes(key.toLowerCase())) return icon;
    }
    return FileText;
}

/* ── Estimate read time from content ───────────────────────── */
function estimateReadTime(content?: string, excerpt?: string): number {
    const text = content || excerpt || '';
    const words = text.split(/\s+/).filter(Boolean).length;
    return Math.max(1, Math.ceil(words / 200));
}

export default function KnowledgeBasePage() {
    const [categories, setCategories] = useState<any[]>([]);
    const [articles, setArticles] = useState<any[]>([]);
    const [selectedCategory, setSelectedCategory] = useState<string>('');
    const [searchQuery, setSearchQuery] = useState('');
    const [searchResults, setSearchResults] = useState<any[] | null>(null);
    const [loading, setLoading] = useState(true);
    const [expandedId, setExpandedId] = useState<string | null>(null);

    useEffect(() => {
        Promise.all([getKBCategories(), getKBArticles()]).then(([cats, arts]) => {
            setCategories(Array.isArray(cats) ? cats : []);
            setArticles(Array.isArray(arts) ? arts : []);
            setLoading(false);
        });
    }, []);

    const handleCategoryClick = async (slug: string) => {
        setSelectedCategory(slug);
        setSearchResults(null);
        setExpandedId(null);
        setLoading(true);
        const arts = await getKBArticles(slug);
        setArticles(Array.isArray(arts) ? arts : []);
        setLoading(false);
    };

    const handleSearch = useCallback(async () => {
        if (!searchQuery.trim()) { setSearchResults(null); return; }
        const results = await searchKBArticles(searchQuery);
        setSearchResults(Array.isArray(results) ? results : []);
    }, [searchQuery]);

    const displayArticles = searchResults || articles;

    return (
        <div className="min-h-screen bg-[#FDFBF7]">
            {/* ═══════════════ HERO SECTION ═══════════════ */}
            <section className="relative min-h-[60vh] flex items-center justify-center overflow-hidden py-24 px-6">
                {/* Ayurvedic Texture Background */}
                <div 
                    className="absolute inset-0 z-0 opacity-40 bg-repeat bg-center"
                    style={{ 
                        backgroundImage: "url('/ayurvedic-texture.png')",
                        backgroundSize: '400px',
                        filter: 'sepia(0.2) contrast(1.1)'
                    }}
                ></div>

                {/* Decorative Elements */}
                <div className="absolute top-0 left-0 w-full h-full bg-gradient-to-br from-[#4A5D23]/20 via-transparent to-[#4A5D23]/5 z-0"></div>
                <div className="absolute -top-24 -right-24 w-96 h-96 bg-[#4A5D23]/10 rounded-full blur-3xl"></div>
                <div className="absolute -bottom-24 -left-24 w-96 h-96 bg-[#8B4513]/5 rounded-full blur-3xl"></div>

                <div className="max-w-4xl mx-auto text-center relative z-10">
                    {/* Resource Hub badge */}
                    <div className="inline-flex items-center gap-3 bg-white/40 backdrop-blur-md border border-[#4A5D23]/10 rounded-full px-6 py-2 mb-10 shadow-sm">
                        <Sparkles className="h-4 w-4 text-[#4A5D23]" />
                        <span className="text-xs font-black tracking-[0.2em] uppercase text-[#1a2408]">Vedashi Resource Hub</span>
                    </div>

                    <h1 className="text-5xl md:text-7xl font-bold text-[#1a2408] mb-8 leading-tight">
                        Sacred <span className="text-[#4A5D23]">Knowledge</span> Archive
                    </h1>

                    <p className="text-[#5B4A31] text-lg md:text-xl max-w-2xl mx-auto mb-12 font-medium leading-relaxed">
                        Deep dive into our collection of herbal guides, traditional practices, and modern Ayurvedic research.
                    </p>

                    {/* Search bar */}
                    <div className="relative max-w-2xl mx-auto group">
                        <div className="absolute -inset-1 bg-gradient-to-r from-[#4A5D23]/20 to-[#8B4513]/20 rounded-[30px] blur opacity-25 group-focus-within:opacity-100 transition duration-1000"></div>
                        <div className="relative">
                            <input
                                type="text"
                                value={searchQuery}
                                onChange={(e) => {
                                    setSearchQuery(e.target.value);
                                    if (!e.target.value.trim()) setSearchResults(null);
                                }}
                                onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
                                placeholder="Search the archive..."
                                className="w-full pl-16 pr-20 py-6 rounded-[24px] bg-white/90 backdrop-blur-xl text-[#1a2408] placeholder-[#5B4A31]/40 text-lg focus:outline-none focus:ring-2 focus:ring-[#4A5D23]/20 shadow-2xl transition-all border border-[#4A5D23]/5"
                            />
                            <Search className="absolute left-6 top-1/2 -translate-y-1/2 h-6 w-6 text-[#4A5D23]" />
                            <button
                                onClick={handleSearch}
                                className="absolute right-3 top-1/2 -translate-y-1/2 w-14 h-14 bg-[#4A5D23] text-white rounded-2xl flex items-center justify-center hover:bg-[#3a491b] hover:scale-105 transition-all cursor-pointer shadow-lg"
                            >
                                <ArrowRight className="h-6 w-6" />
                            </button>
                        </div>
                    </div>
                </div>
            </section>

            {/* ═══════════════ MAIN CONTENT ═══════════════ */}
            <div className="max-w-7xl mx-auto px-6 py-20">

                {/* Search results header */}
                {searchResults && (
                    <div className="flex items-center justify-between mb-12 animate-in fade-in slide-in-from-top-4">
                        <h2 className="text-3xl font-bold text-[#1a2408]">
                            {searchResults.length > 0
                                ? `${searchResults.length} Wisdom Found for "${searchQuery}"`
                                : 'No results found in the hub'}
                        </h2>
                        <button
                            onClick={() => { setSearchQuery(''); setSearchResults(null); }}
                            className="text-sm font-black uppercase tracking-widest text-[#4A5D23] hover:text-[#3a491b] flex items-center gap-2 cursor-pointer bg-white px-6 py-3 rounded-full border border-[#4A5D23]/5 shadow-sm"
                        >
                            <ChevronLeft className="h-4 w-4" /> Clear Search
                        </button>
                    </div>
                )}

                {/* Category filter pills */}
                {!searchResults && categories.length > 0 && (
                    <div className="flex flex-wrap items-center justify-center gap-4 mb-20">
                        <button
                            onClick={() => {
                                setSelectedCategory('');
                                setExpandedId(null);
                                setLoading(true);
                                getKBArticles().then(a => { setArticles(Array.isArray(a) ? a : []); setLoading(false); });
                            }}
                            className={`px-8 py-3 rounded-[20px] text-sm font-black uppercase tracking-widest transition-all cursor-pointer shadow-sm ${!selectedCategory
                                ? 'bg-[#4A5D23] text-white shadow-[#4A5D23]/30 shadow-lg'
                                : 'bg-white text-[#5B4A31] border border-[#4A5D23]/5 hover:border-[#4A5D23]/30'
                                }`}
                        >
                            All Articles
                        </button>
                        {categories.map((cat: any) => (
                            <button
                                key={cat.category_id}
                                onClick={() => handleCategoryClick(cat.slug)}
                                className={`px-8 py-3 rounded-[20px] text-sm font-black uppercase tracking-widest transition-all cursor-pointer shadow-sm ${selectedCategory === cat.slug
                                    ? 'bg-[#4A5D23] text-white shadow-[#4A5D23]/30 shadow-lg'
                                    : 'bg-white text-[#5B4A31] border border-[#4A5D23]/5 hover:border-[#4A5D23]/30'
                                    }`}
                            >
                                {cat.name}
                            </button>
                        ))}
                    </div>
                )}

                {/* Article cards grid */}
                {loading ? (
                    /* Loading skeleton */
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-10">
                        {[...Array(6)].map((_, i) => (
                            <div key={i} className="bg-white rounded-[40px] p-10 animate-pulse border border-[#4A5D23]/5 h-[400px]">
                                <div className="flex items-center justify-between mb-8">
                                    <div className="h-6 bg-gray-100 rounded-full w-24" />
                                    <div className="h-4 bg-gray-50 rounded w-16" />
                                </div>
                                <div className="w-16 h-16 bg-gray-100 rounded-2xl mb-8" />
                                <div className="h-8 bg-gray-100 rounded w-3/4 mb-4" />
                                <div className="h-4 bg-gray-50 rounded w-full mb-2" />
                                <div className="h-4 bg-gray-50 rounded w-2/3" />
                            </div>
                        ))}
                    </div>
                ) : displayArticles.length === 0 ? (
                    /* Empty state */
                    <div className="text-center py-32 bg-white rounded-[60px] border border-[#4A5D23]/5 shadow-xl">
                        <div className="w-24 h-24 rounded-[30px] bg-[#4A5D23]/10 flex items-center justify-center mx-auto mb-10">
                            <BookOpen className="h-10 w-10 text-[#4A5D23]" />
                        </div>
                        <h3 className="text-3xl font-bold text-[#1a2408] mb-4">The library is currently silent</h3>
                        <p className="text-lg text-[#5B4A31] max-w-sm mx-auto font-medium">
                            {searchResults ? 'Our archive doesn\'t seem to contain that wisdom. Try adjusting your search.' : 'Our scholars are preparing new guides for you.'}
                        </p>
                    </div>
                ) : (
                    /* Article cards */
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-10">
                        {displayArticles.map((article: any) => {
                            const Icon = getCategoryIcon(article.category_name);
                            const readTime = estimateReadTime(article.content, article.excerpt);
                            const isExpanded = expandedId === article.article_id;

                            return (
                                <div
                                    key={article.article_id}
                                    className="bg-white rounded-[40px] border border-[#4A5D23]/5 overflow-hidden hover:shadow-[0_32px_64px_-16px_rgba(74,93,35,0.12)] hover:-translate-y-2 transition-all duration-500 group flex flex-col"
                                >
                                    <div className="p-10 flex-1 flex flex-col">
                                        {/* Top meta row */}
                                        <div className="flex items-center justify-between mb-8">
                                            {article.category_name && (
                                                <span className="text-[10px] font-black uppercase tracking-[0.2em] text-[#4A5D23] bg-[#4A5D23]/5 px-4 py-1.5 rounded-full">
                                                    {article.category_name}
                                                </span>
                                            )}
                                            <div className="flex items-center gap-1.5 text-xs font-bold text-[#5B4A31]/50">
                                                <Clock className="h-3.5 w-3.5" />
                                                {readTime} MIN READ
                                            </div>
                                        </div>

                                        {/* Icon */}
                                        <div className="w-16 h-16 rounded-2xl bg-[#4A5D23]/5 flex items-center justify-center mb-8 group-hover:bg-[#4A5D23] transition-all duration-500 shadow-inner">
                                            <Icon className="h-7 w-7 text-[#4A5D23] group-hover:text-white transition-colors duration-500" />
                                        </div>

                                        {/* Title */}
                                        <h3 className="text-xl md:text-2xl font-bold text-[#1a2408] mb-4 leading-snug group-hover:text-[#4A5D23] transition-colors">
                                            {article.title}
                                        </h3>

                                        {/* Excerpt */}
                                        {article.excerpt && (
                                            <p className="text-base text-[#5B4A31] leading-relaxed mb-6 flex-1 line-clamp-3 font-medium">
                                                {article.excerpt}
                                            </p>
                                        )}

                                        {/* Expanded content preview */}
                                        <div className={`overflow-hidden transition-all duration-500 ease-in-out ${isExpanded ? 'max-h-[500px] mb-6' : 'max-h-0'}`}>
                                            <div className="text-sm text-[#5B4A31] leading-relaxed border-t border-[#4A5D23]/10 pt-6 whitespace-pre-line font-medium">
                                                {article.content?.substring(0, 400)}
                                                {article.content && article.content.length > 400 && '...'}
                                            </div>
                                        </div>
                                    </div>

                                    {/* Footer action */}
                                    <div className="px-10 pb-10">
                                        <div className="flex items-center gap-6">
                                            <button
                                                onClick={() => setExpandedId(isExpanded ? null : article.article_id)}
                                                className="inline-flex items-center gap-2 text-xs font-black uppercase tracking-widest text-[#5B4A31] hover:text-[#4A5D23] transition-colors cursor-pointer group/btn"
                                            >
                                                {isExpanded ? 'Collapse' : 'Sneak Peek'}
                                                <ChevronDown className={`h-4 w-4 transition-transform duration-500 ${isExpanded ? 'rotate-180' : ''}`} />
                                            </button>
                                            <Link
                                                href={`/help-center/knowledge-base/${article.slug}`}
                                                className="inline-flex items-center gap-3 bg-[#4A5D23]/5 text-[#4A5D23] px-6 py-3 rounded-2xl text-xs font-black uppercase tracking-widest hover:bg-[#4A5D23] hover:text-white transition-all ml-auto hover:shadow-lg"
                                            >
                                                Open Article
                                                <ArrowRight className="h-4 w-4" />
                                            </Link>
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                )}

                {/* Back + Help footer */}
                <div className="mt-32 flex flex-col sm:flex-row items-center justify-between gap-8 border-t border-[#4A5D23]/10 pt-16">
                    <Link
                        href="/help-center"
                        className="inline-flex items-center gap-4 text-lg font-bold text-[#5B4A31] hover:text-[#4A5D23] transition-all group"
                    >
                        <div className="w-14 h-14 rounded-2xl bg-white shadow-xl flex items-center justify-center group-hover:bg-[#4A5D23] group-hover:text-white transition-all">
                            <ChevronLeft className="h-7 w-7" />
                        </div>
                        Help Center Home
                    </Link>
                    <Link
                        href="/help-center/support"
                        className="inline-flex items-center gap-4 bg-[#4A5D23] text-white px-10 py-5 rounded-2xl text-lg font-black uppercase tracking-widest hover:bg-[#3a491b] transition-all shadow-2xl hover:-translate-y-1"
                    >
                        <HeadphonesIcon className="h-6 w-6" />
                        Request Support
                    </Link>
                </div>
            </div>
        </div>

    );
}

'use client';

import { useState, useEffect } from 'react';
import Link from 'next/link';
import { useParams } from 'next/navigation';
import { Search, MessageSquare, HelpCircle, BookOpen, FileText, ChevronRight, Send } from 'lucide-react';
import { getFaqs, getHelpArticles, searchFaqs, searchHelpArticles, searchKBArticles } from '@/lib/api';

export default function HelpCenterPage() {
    const params = useParams();
    const country = params?.country || 'in';
    const [searchQuery, setSearchQuery] = useState('');
    const [searchResults, setSearchResults] = useState<any[]>([]);
    const [searching, setSearching] = useState(false);
    const [popularFaqs, setPopularFaqs] = useState<any[]>([]);

    useEffect(() => {
        getFaqs().then((data: any) => {
            const faqs = data?.faqs || [];
            setPopularFaqs(faqs.slice(0, 5));
        });
    }, []);

    const handleSearch = async () => {
        if (!searchQuery.trim()) return;
        setSearching(true);
        try {
            const [faqResults, helpResults, kbResults] = await Promise.all([
                searchFaqs(searchQuery),
                searchHelpArticles(searchQuery),
                searchKBArticles(searchQuery),
            ]);
            const combined = [
                ...(Array.isArray(faqResults) ? faqResults.map((f: any) => ({ ...f, _type: 'faq' })) : []),
                ...(Array.isArray(helpResults) ? helpResults.map((a: any) => ({ ...a, _type: 'help' })) : []),
                ...(Array.isArray(kbResults) ? kbResults.map((a: any) => ({ ...a, _type: 'kb' })) : []),
            ];
            setSearchResults(combined);
        } catch {
            setSearchResults([]);
        } finally {
            setSearching(false);
        }
    };

    const sections = [
        {
            title: 'FAQs',
            desc: 'Find quick answers to common questions about orders, payments, and more.',
            icon: HelpCircle,
            href: `/${country}/help-center/faq`,
            color: '#722F37',
        },
        {
            title: 'Knowledge Base',
            desc: 'Browse detailed guides, tutorials, and documentation.',
            icon: BookOpen,
            href: `/${country}/help-center/knowledge-base`,
            color: '#8B4513',
        },
        {
            title: 'Support Tickets',
            desc: 'Submit a support request or track your existing tickets.',
            icon: MessageSquare,
            href: `/${country}/help-center/support`,
            color: '#4b0f1a',
        },
        {
            title: 'Customer Enquiry',
            desc: 'Share your thoughts, report an issue or contact us.',
            icon: Send,
            href: `/${country}/help-center/customer-enquiry`,
            color: '#5B3A29',
        },
    ];

    return (
        <div className="min-h-screen bg-[#FDFBF7]">
            {/* Hero Section */}
            <section className="relative py-24 px-6 overflow-hidden">
                {/* Ayurvedic Texture Background */}
                <div 
                    className="absolute inset-0 z-0 opacity-40 bg-repeat bg-center"
                    style={{ 
                        backgroundImage: "url('/ayurvedic-texture.png')",
                        backgroundSize: '400px',
                        filter: 'sepia(0.2) contrast(1.1)'
                    }}
                ></div>
                
                {/* Decorative Elements */}
                <div className="absolute top-0 left-0 w-full h-full bg-gradient-to-b from-[#4A5D23]/10 to-transparent z-0"></div>
                
                <div className="max-w-4xl mx-auto text-center relative z-10">
                    <span className="inline-block px-4 py-1.5 rounded-full bg-[#4A5D23]/50 text-[#2D3A15] text-xs font-bold tracking-widest uppercase mb-6">
                        Vedic Support
                    </span>
                    <h1 className="text-4xl md:text-6xl font-bold text-[#1a2408] mb-6 leading-tight">
                        How can we <span className="text-[#4A5D23]">help you?</span>
                    </h1>
                    <p className="text-[#5B4A31] text-lg mb-8 max-w-2xl mx-auto font-bold leading-relaxed">
                        Find guidance, answers, and support for your Ayurvedic journey.
                    </p>
                    <div className="relative max-w-2xl mx-auto group">
                        <div className="absolute -inset-1 bg-gradient-to-r from-[#4A5D23]/20 to-[#8B4513]/20 rounded-2xl blur opacity-25 group-hover:opacity-50 transition duration-1000 group-hover:duration-200"></div>
                        <div className="relative">
                            <input
                                type="text"
                                value={searchQuery}
                                onChange={(e) => setSearchQuery(e.target.value)}
                                onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
                                placeholder="Search for help articles, FAQs, guides..."
                                className="w-full pl-14 pr-32 py-5 rounded-2xl bg-white/90 backdrop-blur-sm text-gray-900 placeholder-gray-400 text-lg border border-[#4A5D23]/10 focus:outline-none focus:ring-2 focus:ring-[#4A5D23] shadow-2xl transition-all"
                            />
                            <Search className="absolute left-5 top-1/2 -translate-y-1/2 h-6 w-6 text-[#4A5D23]" />
                            <button
                                onClick={handleSearch}
                                className="absolute right-2.5 top-1/2 -translate-y-1/2 bg-[#4A5D23] text-white px-8 py-3 rounded-xl text-base font-semibold hover:bg-[#3a491b] transition-all shadow-lg active:scale-95"
                            >
                                Search
                            </button>
                        </div>
                    </div>
                </div>
            </section>

            {/* Search Results */}
            {(searchResults.length > 0 || searching) && (
                <section className="max-w-4xl mx-auto px-6 py-8">
                    <h2 className="text-xl font-bold text-[#1a2408] mb-6 flex items-center gap-2">
                        <div className="w-2 h-8 bg-[#4A5D23] rounded-full"></div>
                        {searching ? 'Finding answers...' : `${searchResults.length} result${searchResults.length !== 1 ? 's' : ''} found`}
                    </h2>
                    {!searching && (
                        <div className="grid gap-4">
                            {searchResults.map((item, i) => (
                                <Link
                                    key={i}
                                    href={
                                        item._type === 'faq'
                                            ? `/${country}/help-center/faq`
                                            : item._type === 'help'
                                                ? `/${country}/help-center/${item.slug || ''}`
                                                : `/${country}/help-center/knowledge-base/${item.slug || ''}`
                                    }
                                    className="block bg-white/60 backdrop-blur-sm rounded-2xl p-5 border border-[#4A5D23]/5 hover:border-[#4A5D23]/30 hover:shadow-xl hover:-translate-y-0.5 transition-all duration-300 group"
                                >
                                    <div className="flex items-start gap-4">
                                        <div className="bg-[#4A5D23]/10 p-2 rounded-lg group-hover:bg-[#4A5D23] transition-colors">
                                            <FileText className="h-5 w-5 text-[#4A5D23] group-hover:text-white" />
                                        </div>
                                        <div>
                                            <div className="flex items-center gap-3 mb-1">
                                                <h3 className="font-bold text-[#1a2408] group-hover:text-[#4A5D23] transition-colors">
                                                    {item.question || item.title}
                                                </h3>
                                                <span className="text-[10px] uppercase tracking-widest font-black px-2 py-0.5 rounded-md bg-[#4A5D23]/10 text-[#4A5D23]">
                                                    {item._type === 'faq' ? 'FAQ' : item._type === 'help' ? 'Help' : 'Guide'}
                                                </span>
                                            </div>
                                            <p className="text-sm text-[#5B4A31] line-clamp-2">
                                                {item.answer || item.excerpt || item.content?.substring(0, 150) + '...'}
                                            </p>
                                        </div>
                                    </div>
                                </Link>
                            ))}
                        </div>
                    )}
                </section>
            )}

            {/* Quick-access Cards */}
            <section className="max-w-6xl mx-auto px-6 -mt-10 relative z-10 mb-20">
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                    {sections.map((section) => {
                        const Icon = section.icon;
                        const herbalColors = [
                            { bg: '#E8EDDF', text: '#4A5D23' },
                            { bg: '#F2E8CF', text: '#8B4513' },
                            { bg: '#E9F5F2', text: '#2E5A50' },
                            { bg: '#F9F1E7', text: '#A67C52' }
                        ];
                        const colorIdx = sections.indexOf(section) % herbalColors.length;
                        const theme = herbalColors[colorIdx];

                        return (
                            <Link
                                key={section.title}
                                href={section.href}
                                className="group relative bg-white rounded-3xl p-8 border border-[#4A5D23]/5 hover:border-[#4A5D23]/20 shadow-sm hover:shadow-2xl transition-all duration-500 overflow-hidden"
                            >
                                <div className="absolute top-0 right-0 w-24 h-24 bg-gradient-to-br from-[#4A5D23]/5 to-transparent rounded-bl-[100px] -mr-4 -mt-4 group-hover:w-32 group-hover:h-32 transition-all duration-500"></div>
                                
                                <div
                                    className="w-16 h-16 rounded-2xl flex items-center justify-center mb-6 transition-all duration-500 group-hover:rotate-6 group-hover:scale-110 shadow-inner"
                                    style={{ backgroundColor: theme.bg }}
                                >
                                    <Icon className="h-8 w-8" style={{ color: theme.text }} />
                                </div>
                                <h3 className="text-xl font-bold text-[#1a2408] mb-3">{section.title}</h3>
                                <p className="text-sm text-[#5B4A31] leading-relaxed mb-6">{section.desc}</p>
                                <div 
                                    className="inline-flex items-center gap-2 text-sm font-bold tracking-wide transition-all duration-300 group-hover:gap-3"
                                    style={{ color: theme.text }}
                                >
                                    Explore More <ChevronRight className="h-4 w-4" />
                                </div>
                            </Link>
                        );
                    })}
                </div>
            </section>

            {/* Popular FAQs */}
            {popularFaqs.length > 0 && (
                <section className="max-w-5xl mx-auto px-6 py-20 bg-[#FDFBF7] rounded-[50px] mb-20 border border-[#4A5D23]/5">
                    <div className="text-center mb-12">
                        <h2 className="text-3xl md:text-4xl font-bold text-[#1a2408] mb-4">Common Questions</h2>
                        <div className="w-24 h-1 bg-[#4A5D23] mx-auto rounded-full opacity-30"></div>
                    </div>
                    <div className="grid md:grid-cols-1 gap-4 max-w-3xl mx-auto">
                        {popularFaqs.map((faq: any) => (
                            <Link
                                key={faq.faq_id}
                                href={`/${country}/help-center/faq`}
                                className="flex items-center justify-between bg-white rounded-2xl p-6 border border-[#4A5D23]/5 hover:border-[#4A5D23]/20 hover:shadow-md transition-all group"
                            >
                                <div className="flex items-center gap-4">
                                    <div className="w-10 h-10 rounded-full bg-[#4A5D23]/5 flex items-center justify-center group-hover:bg-[#4A5D23] transition-colors">
                                        <HelpCircle className="h-5 w-5 text-[#4A5D23] group-hover:text-white" />
                                    </div>
                                    <span className="text-base font-semibold text-[#1a2408]">{faq.question}</span>
                                </div>
                                <div className="p-2 rounded-lg bg-gray-50 group-hover:bg-[#4A5D23]/10 transition-colors">
                                    <ChevronRight className="h-5 w-5 text-[#4A5D23]" />
