                    </div>

                </div>
            </div>

            {/* ── Right Card ── */}
            <div className="relative z-20 w-full lg:w-[480px] xl:w-[540px] flex-shrink-0 h-full flex flex-col justify-center lg:py-8 lg:pr-8">
