'use client';

import { useState, useRef, useEffect } from 'react';
import { useRouter, usePathname } from 'next/navigation';
import { useCurrency } from '@/context/CurrencyContext';
import { SUPPORTED_COUNTRIES } from '@/lib/currency';
import { ChevronDown, Globe } from 'lucide-react';

export default function RegionSwitcher({ upward = false }: { upward?: boolean }) {
  const { countryConfig } = useCurrency();
  const router = useRouter();
  const pathname = usePathname();
  const [isOpen, setIsOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const parts = pathname.split('/');
  const urlCountry = parts[1];
  const isValidCountry = Object.keys(SUPPORTED_COUNTRIES).includes(urlCountry);
  const country = isValidCountry ? urlCountry : 'in';

  // Close dropdown when clicking outside
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    }
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleSelect = (newCountry: string) => {
    setIsOpen(false);
    if (newCountry === country) return;

    // Set cookies (7 days)
    document.cookie = `geo_country=${newCountry}; max-age=${7 * 24 * 60 * 60}; path=/`;
    const currencyMap: Record<string, string> = { in: 'INR', us: 'USD', gb: 'GBP', ae: 'AED', ca: 'CAD', au: 'AUD', ru: 'RUB', kr: 'KRW' };
    document.cookie = `geo_currency=${currencyMap[newCountry] || 'USD'}; max-age=${7 * 24 * 60 * 60}; path=/`;

    // Replace country code in pathname
    const parts = pathname.split('/');
    // Check if the current pathname has a valid country slug
    const hasCountryPrefix = Object.keys(SUPPORTED_COUNTRIES).includes(parts[1]);

    let newPath = `/${newCountry}`;
    if (hasCountryPrefix) {
      if (parts.length > 2) {
        newPath += '/' + parts.slice(2).join('/');
      }
    } else {
      // If for some reason it doesn't have a prefix (e.g. root), just append
      // But typically middleware handles this. We will just redirect to the new route.
      newPath += pathname === '/' ? '' : pathname;
    }

    // Retain query params if any
    const search = window.location.search;
    router.push(newPath + search);
    router.refresh();
  };

  const currentCountryConfig = SUPPORTED_COUNTRIES[country as keyof typeof SUPPORTED_COUNTRIES];

  return (
    <div className="relative inline-block text-left" ref={dropdownRef}>
      <button
        suppressHydrationWarning
        type="button"
        onClick={() => setIsOpen(!isOpen)}
        className="flex items-center gap-1.5 p-2 rounded-lg hover:bg-gray-100 transition-colors group"
        aria-expanded={isOpen}
      >
        <span className="text-base leading-none">{currentCountryConfig.flag}</span>
        <span className="text-xs font-bold text-gray-700 uppercase">{currentCountryConfig.currency}</span>
        <ChevronDown className={`h-3.5 w-3.5 text-gray-500 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
      </button>

      {isOpen && (
        <div className={`absolute left-0 sm:left-auto sm:right-0 w-48 rounded-xl bg-white shadow-xl ring-1 ring-black/5 z-50 overflow-hidden ${upward ? 'bottom-full mb-2 origin-bottom-left sm:origin-bottom-right' : 'mt-2 origin-top-left sm:origin-top-right'} animate-in fade-in ${upward ? 'slide-in-from-bottom-2' : 'slide-in-from-top-2'} duration-200`}>
          <div className="p-1">
            {Object.entries(SUPPORTED_COUNTRIES).map(([code, config]) => (
              <button
                key={code}
                onClick={() => handleSelect(code)}
                className={`w-full flex items-center justify-between px-3 py-2.5 text-sm rounded-lg transition-colors ${country === code
                  ? 'bg-[#3B5D3B]/10 text-[#3B5D3B] font-bold'
                  : 'text-gray-700 hover:bg-gray-50 font-medium'
                  }`}
              >
                <div className="flex items-center gap-2.5">
                  <span className="text-base">{config.flag}</span>
                  <span>{config.name}</span>
                </div>
                <span className={`text-[10px] tracking-widest uppercase ${country === code ? 'text-[#3B5D3B]' : 'text-gray-400'}`}>
                  {config.currency}
                </span>
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import { useState, useEffect, useRef, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import { Search, X, Loader2 } from 'lucide-react';
import { searchAutocomplete, type SearchSuggestion } from '@/lib/api';

interface SearchAutocompleteProps {
    /** Called when the sea rch overlay should close (e.g. mobile) */
    onClose?: () => void;
    /** Placeholder text */
    placeholder?: string;
    /** Additional wrap per classes */
    className?: string;
} 

export default function SearchAutocomplete({
    onClose,
    placeholder = 'Search products…',
    className = '',
}: SearchAutocompleteProps) {
    const router = useRouter();
    const [query, setQuery] = useState('');
    const [suggestions, setSuggestions] = useState<SearchSuggestion[]>([]);
    const [isOpen, setIsOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(false);
    const [activeIndex, setActiveIndex] = useState(-1);

    const inputRef = useRef<HTMLInputElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);
    const debounceRef = useRef<ReturnType<typeof setTimeout>>(undefined);

    // ── Debounced fetch ────────────────────────────────────────
    const fetchSuggestions = useCallback(async (term: string) => {
        if (term.trim().length < 2) {
            setSuggestions([]);
            setIsOpen(false);
            return;
        }

        setIsLoading(true);
        try {
            const results = await searchAutocomplete(term);
            setSuggestions(results);
        } catch {
            setSuggestions([]);
        } finally {
            setIsLoading(false);
        }
    }, []);

    useEffect(() => {
        if (debounceRef.current) clearTimeout(debounceRef.current);

        if (query.trim().length < 2) {
            setSuggestions([]);
            setIsOpen(false);
            setIsLoading(false);
            return;
        }

        setIsLoading(true);
        debounceRef.current = setTimeout(() => {
            fetchSuggestions(query);
        }, 300);

        return () => {
            if (debounceRef.current) clearTimeout(debounceRef.current);
        };
    }, [query, fetchSuggestions]);

    // ── Click outside to close ─────────────────────────────────
    useEffect(() => {
        const handleClickOutside = (e: MouseEvent) => {
            if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
                setIsOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    // ── Static Storefront Pages ──
    const storePages = [
        { title: 'Home', path: '/' },
        { title: 'All Products', path: '/products' },
        { title: 'Categories', path: '/categories' },
        { title: 'About Us', path: '/about' },
        { title: 'Contact Support', path: '/contact' },
    ];

    const matchedPages = query.trim().length >= 2
        ? storePages.filter(p => p.title.toLowerCase().includes(query.toLowerCase()))
        : [];

    const totalItems = matchedPages.length + suggestions.length;
    const isShowingViewAll = suggestions.length > 0;
    const maxIndex = isShowingViewAll ? totalItems : totalItems - 1;

    // ── Navigate to product, page, or search page ─────────────────────
    const goToProduct = (id: string) => {
        setIsOpen(false);
        setQuery('');
        onClose?.();
        router.push(`/products/${id}`);
    };

    const goToPage = (path: string) => {
        setIsOpen(false);
        setQuery('');
        onClose?.();
        router.push(path);
    };

    const goToSearch = () => {
        if (!query.trim()) return;
        setIsOpen(false);
        onClose?.();
        router.push(`/search?q=${encodeURIComponent(query.trim())}`);
    };

    // ── Keyboard navigation ────────────────────────────────────
    const handleKeyDown = (e: React.KeyboardEvent) => {
        if (!isOpen && e.key !== 'Enter') return;

        switch (e.key) {
            case 'ArrowDown':
                e.preventDefault();
                setActiveIndex(prev => prev < maxIndex ? prev + 1 : 0);
                break;
            case 'ArrowUp':
                e.preventDefault();
                setActiveIndex(prev => prev > 0 ? prev - 1 : maxIndex);
                break;
            case 'Enter':
                e.preventDefault();
                if (activeIndex >= 0) {
                    if (activeIndex < matchedPages.length) {
                        goToPage(matchedPages[activeIndex].path);
                    } else if (activeIndex < totalItems) {
                        goToProduct(suggestions[activeIndex - matchedPages.length].product_id);
                    } else if (isShowingViewAll) {
                        goToSearch();
                    }
                } else {
                    goToSearch();
                }
                break;
            case 'Escape':
                setIsOpen(false);
                setActiveIndex(-1);
                inputRef.current?.blur();
                break;
        }
    };

    // ── Format price ───────────────────────────────────────────
    const formatPrice = (price?: number) => {
        if (price == null) return '';
        return new Intl.NumberFormat('en-IN', {
            style: 'currency',
            currency: 'INR',
            minimumFractionDigits: 0,
            maximumFractionDigits: 0,
        }).format(price);
    };

    return (
        <div ref={containerRef} className={`relative ${className}`}>
            {/* ─── Search Input ─── */}
            <div className="relative flex items-center">
                <Search className="absolute left-4 h-4 w-4 text-gray-400 pointer-events-none" />
                <input
                    ref={inputRef}
                    type="text"
                    value={query}
                    onChange={e => {
                        setQuery(e.target.value);
                        setActiveIndex(-1);
                        if (e.target.value.trim().length >= 2 && !isOpen) {
                            setIsOpen(true);
                        }
                    }}
                    onFocus={() => {
                        if (suggestions.length > 0 || query.trim().length >= 2) setIsOpen(true);
                    }}
                    onKeyDown={handleKeyDown}
                    placeholder={placeholder}
                    autoComplete="off"
                    className="
            w-full pl-11 pr-9 py-2 rounded-full
            bg-gray-100 border border-gray-200
            text-sm text-gray-800 placeholder-gray-400
            focus:outline-none focus:ring-2 focus:ring-[#4b0f1a]/30 focus:border-[#4b0f1a]/40
            transition-all duration-200
          "
                />
                {/* Clear / Loading indicator */}
                {query && (
                    <button
                        onClick={() => {
                            setQuery('');
                            setSuggestions([]);
                            setIsOpen(false);
                            inputRef.current?.focus();
                        }}
                        className="absolute right-3 p-0.5 text-gray-400 hover:text-gray-600 transition-colors"
                    >
                        {isLoading ? (
                            <Loader2 className="h-4 w-4 animate-spin" />
                        ) : (
                            <X className="h-4 w-4" />
                        )}
                    </button>
                )}
            </div>

            {/* ─── Dropdown Panel ─── */}
            {isOpen && query.trim().length >= 2 && (
                <div className="
          absolute top-full left-0 right-0 mt-1.5 z-[300]
          bg-white rounded-xl shadow-2xl border border-gray-100
          max-h-[420px] overflow-y-auto
          animate-in fade-in slide-in-from-top-1 duration-200
        ">
                    {/* Pages Section */}
                    {matchedPages.length > 0 && (
                        <div className="py-1">
                            <p className="px-4 py-1.5 text-[10px] font-semibold uppercase tracking-wider text-gray-400 bg-gray-50/50">
                                Pages
                            </p>
                            {matchedPages.map((page, index) => (
                                <button
                                    key={page.path}
                                    onClick={() => goToPage(page.path)}
                                    onMouseEnter={() => setActiveIndex(index)}
                                    className={`
                    w-full flex items-center gap-3 px-4 py-2.5 text-left
                    transition-colors duration-100
                    ${activeIndex === index ? 'bg-[#fdf6ee] text-[#4b0f1a]' : 'hover:bg-gray-50 text-gray-700'}
                  `}
                                >
                                    <div className="flex-shrink-0 w-8 h-8 rounded-lg bg-gray-100 flex items-center justify-center">
                                        <Search className="h-3.5 w-3.5 opacity-40" />
                                    </div>
                                    <span className="text-sm font-medium">{page.title}</span>
                                </button>
                            ))}
                        </div>
                    )}

                    {/* Products Section */}
                    {(suggestions.length > 0 || isLoading) && (
                        <div className="py-1 border-t border-gray-100">
                            <p className="px-4 py-1.5 text-[10px] font-semibold uppercase tracking-wider text-gray-400 bg-gray-50/50">
                                Products
                            </p>
                            {isLoading && suggestions.length === 0 && (
                                <div className="flex items-center gap-2 px-4 py-3 text-sm text-gray-400">
                                    <Loader2 className="h-4 w-4 animate-spin" />
                                    Searching...
                                </div>
                            )}
                            {suggestions.map((item, index) => {
                                const globalIndex = index + matchedPages.length;
                                return (
                                    <button
                                        key={item.product_id}
                                        onClick={() => goToProduct(item.product_id)}
                                        onMouseEnter={() => setActiveIndex(globalIndex)}
                                        className={`
                      w-full flex items-center gap-3 px-4 py-3 text-left
                      transition-colors duration-100 border-b border-gray-50 last:border-b-0
                      ${activeIndex === globalIndex ? 'bg-[#fdf6ee]' : 'hover:bg-gray-50'}
                    `}
                                    >
                                        {/* Thumbnail */}
                                        <div className="flex-shrink-0 w-10 h-10 rounded-lg bg-gray-100 overflow-hidden">
                                            {item.thumbnail_url ? (
                                                <img
                                                    src={item.thumbnail_url}
                                                    alt={item.product_name}
                                                    className="w-full h-full object-cover"
                                                    loading="lazy"
                                                />
                                            ) : (
                                                <div className="w-full h-full flex items-center justify-center text-gray-300">
                                                    <Search className="h-4 w-4" />
                                                </div>
                                            )}
                                        </div>

                                        {/* Text */}
                                        <div className="flex-1 min-w-0">
                                            <p className="text-sm font-medium text-gray-900 truncate">
                                                {item.product_name}
                                            </p>
                                            <p className="text-xs text-gray-500 truncate">
                                                {[item.brand, item.category].filter(Boolean).join(' · ')}
                                            </p>
                                        </div>

                                        {/* Price */}
                                        {item.price != null && (
                                            <span className="flex-shrink-0 text-sm font-semibold text-[#4b0f1a]">
                                                {formatPrice(item.price)}
                                            </span>
                                        )}
                                    </button>
                                );
                            })}
                        </div>
                    )}

                    {/* Empty state */}
                    {!isLoading && matchedPages.length === 0 && suggestions.length === 0 && (
                        <div className="px-4 py-6 text-center text-sm text-gray-400">
                            No results found for &ldquo;{query}&rdquo;
                        </div>
                    )}

                    {/* View All Results Link */}
                    {isShowingViewAll && (
                        <button
                            onClick={goToSearch}
                            onMouseEnter={() => setActiveIndex(totalItems)}
                            className={`
                w-full flex items-center justify-center gap-2 px-4 py-3 border-t border-gray-100
                text-sm font-medium transition-colors duration-100
                ${activeIndex === totalItems
                                    ? 'bg-[#4b0f1a] text-white'
                                    : 'bg-[#fdf6ee] text-[#4b0f1a] hover:bg-[#4b0f1a] hover:text-white'
                                }
                rounded-b-xl
              `}
                        >
                            <Search className="h-3.5 w-3.5" />
                            View all results for &ldquo;{query}&rdquo;
                        </button>
                    )}
                </div>
            )}
        </div>
    );
}

'use client';

import { useState, useEffect, useRef, useCallback } from 'react';
import { useRouter, usePathname } from 'next/navigation';
import { Search, X, Loader2, Sparkles } from 'lucide-react';
import { getSearchSuggestions, SearchSuggestion } from '@/lib/api';
import Image from 'next/image';
import Link from 'next/link';

interface SearchBarProps {
    /** Current search value (from URL / filter state) */
    value: string;
    /** Called when user commits a search (Enter or suggestion click) */
    onSearch: (query: string) => void;
    /** Visual variant */
    variant?: 'hero' | 'compact';
    placeholder?: string;
    className?: string;
    autoFocus?: boolean;
    /** If true, calls onSearch immediately as user types (debounced) and hides separate suggestions Panel */
    live?: boolean;
}

function useDebounce<T>(value: T, delay: number): T {
    const [debounced, setDebounced] = useState(value);
    useEffect(() => {
        const t = setTimeout(() => setDebounced(value), delay);
        return () => clearTimeout(t);
    }, [value, delay]);
    return debounced;
}

export default function SearchBar({
    value,
    onSearch,
    variant = 'hero',
    placeholder = 'Search products, brands, or categories...',
    className = '',
    autoFocus = false,
    live = false,
}: SearchBarProps) {
    const router = useRouter();
    const pathname = usePathname();

    const [inputValue, setInputValue] = useState(value);
    const [suggestions, setSuggestions] = useState<SearchSuggestion[]>([]);
    const [suggestionsOpen, setSuggestionsOpen] = useState(false);
    const [loading, setLoading] = useState(false);
    const [activeIndex, setActiveIndex] = useState(-1);

    const inputRef = useRef<HTMLInputElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);

    // Sync external value to local (e.g., on clearAll)
    useEffect(() => {
        setInputValue(value);
    }, [value]);

    const debouncedInput = useDebounce(inputValue, 300);

    // Fetch suggestions / trigger live search whenever debounced input changes
    useEffect(() => {
        if (debouncedInput.trim().length < 2) {
            setSuggestions([]);
            setSuggestionsOpen(false);
            setLoading(false);
            // If live mode, clear search when input is too short
            if (live && value !== '') onSearch('');
            return;
        }

        if (live) {
            onSearch(debouncedInput.trim());
            return;
        }

        let cancelled = false;
        setLoading(true);
        getSearchSuggestions(debouncedInput).then(results => {
            if (!cancelled) {
                setSuggestions(results);
                setSuggestionsOpen(results.length > 0);
                setLoading(false);
            }
        });
        return () => { cancelled = true; };
    }, [debouncedInput, live]);

    // Close dropdown on outside click
    useEffect(() => {
        const handler = (e: MouseEvent) => {
            if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
                setSuggestionsOpen(false);
                setActiveIndex(-1);
            }
        };
        document.addEventListener('mousedown', handler);
        return () => document.removeEventListener('mousedown', handler);
    }, []);

    const commitSearch = useCallback((q: string) => {
        setSuggestionsOpen(false);
        setActiveIndex(-1);
        onSearch(q.trim());
        inputRef.current?.blur();
    }, [onSearch]);

    const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
        if (!suggestionsOpen) {
            if (e.key === 'Enter') commitSearch(inputValue);
            return;
        }
        if (e.key === 'ArrowDown') {
            e.preventDefault();
            setActiveIndex(i => Math.min(i + 1, suggestions.length - 1));
        } else if (e.key === 'ArrowUp') {
            e.preventDefault();
            setActiveIndex(i => Math.max(i - 1, -1));
        } else if (e.key === 'Enter') {
            e.preventDefault();
            if (activeIndex >= 0 && suggestions[activeIndex]) {
                const s = suggestions[activeIndex];
                setInputValue(s.product_name);
                commitSearch(s.product_name);
            } else {
                commitSearch(inputValue);
            }
        } else if (e.key === 'Escape') {
            setSuggestionsOpen(false);
            setActiveIndex(-1);
        }
    };

    const handleSuggestionClick = (s: SearchSuggestion) => {
        setInputValue(s.product_name);
        commitSearch(s.product_name);
    };

    const handleClear = () => {
        setInputValue('');
        setSuggestions([]);
        setSuggestionsOpen(false);
        onSearch('');
        inputRef.current?.focus();
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        commitSearch(inputValue);
    };

    const isHero = variant === 'hero';

    return (
        <div ref={containerRef} className={`relative ${className}`}>
            <form onSubmit={handleSubmit} className="relative">
                {/* Search icon */}
                <Search className={`absolute left-4 top-1/2 -translate-y-1/2 pointer-events-none ${isHero ? 'h-4 w-4 text-white/60' : 'h-4 w-4 text-gray-400'}`} />

                <input
                    ref={inputRef}
                    type="text"
                    value={inputValue}
                    onChange={e => { setInputValue(e.target.value); setSuggestionsOpen(false); }}
                    onFocus={() => { if (suggestions.length > 0) setSuggestionsOpen(true); }}
                    onKeyDown={handleKeyDown}
                    placeholder={placeholder}
                    autoFocus={autoFocus}
                    autoComplete="off"
                    spellCheck={false}
                    className={
                        isHero
                            ? 'w-full px-5 py-3 pl-12 pr-20 rounded-full bg-white/15 backdrop-blur-sm border border-white/25 text-white text-sm placeholder-white/50 focus:outline-none focus:ring-2 focus:ring-white/30 focus:bg-white/20 transition-all'
                            : 'w-full px-4 py-2.5 pl-10 pr-16 rounded-xl bg-white border border-gray-200 text-gray-800 text-sm placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-[#3d5c3a]/20 focus:border-[#3d5c3a] transition-all'
                    }
                    aria-label="Search products"
                    aria-autocomplete="list"
                    aria-expanded={suggestionsOpen}
                    aria-controls="search-suggestions"
                    role="combobox"
                />

                {/* Right side: loader / clear / submit */}
                <div className="absolute right-3 top-1/2 -translate-y-1/2 flex items-center gap-1">
                    {loading && <Loader2 className={`h-4 w-4 animate-spin ${isHero ? 'text-white/60' : 'text-[#3d5c3a]'}`} />}
                    {inputValue && !loading && (
                        <button
                            type="button"
                            onClick={handleClear}
                            className={`p-1 rounded-full transition-colors cursor-pointer ${isHero ? 'hover:bg-white/10' : 'hover:bg-gray-100'}`}
                            aria-label="Clear search"
                        >
                            <X className={`h-3.5 w-3.5 ${isHero ? 'text-white/60' : 'text-gray-400'}`} />
                        </button>
                    )}
                    {inputValue && (
                        <button
                            type="submit"
                            className={`text-[10px] font-bold px-2 py-1 rounded-full cursor-pointer transition-colors ${isHero ? 'bg-white/20 text-white hover:bg-white/30' : 'bg-[#3d5c3a] text-white hover:bg-[#2d4a2a]'}`}
                            aria-label="Search"
                        >
                            Go
                        </button>
                    )}
                </div>
            </form>

            {/* Suggestions Dropdown - ONLY show in non-live mode */}
            {!live && suggestionsOpen && suggestions.length > 0 && (
                <div
                    id="search-suggestions"
                    role="listbox"
                    className="absolute top-full left-0 right-0 mt-2 bg-white rounded-2xl shadow-2xl border border-gray-100 overflow-hidden z-50 animate-in fade-in slide-in-from-top-2 duration-150"
                >
                    <div className="px-3 py-2 border-b border-gray-50 flex items-center gap-1.5">
                        <Sparkles className="h-3 w-3 text-[#3d5c3a]" />
                        <span className="text-[10px] font-bold uppercase tracking-widest text-gray-400">Suggestions</span>
                    </div>
                    <ul className="max-h-80 overflow-y-auto">
                        {suggestions.map((s, i) => (
                            <li
                                key={s.product_id}
                                role="option"
                                aria-selected={i === activeIndex}
                                className={`flex items-center gap-3 px-4 py-3 cursor-pointer transition-colors ${i === activeIndex ? 'bg-[#3d5c3a]/5' : 'hover:bg-gray-50'}`}
                                onMouseEnter={() => setActiveIndex(i)}
                                onMouseDown={e => e.preventDefault()} // Prevent blur before click
                                onClick={() => handleSuggestionClick(s)}
                            >
                                {/* Thumbnail */}
                                <div className="h-10 w-10 rounded-xl overflow-hidden bg-gray-100 flex-shrink-0">
                                    {s.thumbnail_url ? (
                                        <img
                                            src={s.thumbnail_url}
                                            alt={s.product_name}
                                            className="h-full w-full object-cover"
                                        />
                                    ) : (
                                        <div className="h-full w-full flex items-center justify-center">
                                            <Search className="h-4 w-4 text-gray-300" />
                                        </div>
                                    )}
                                </div>
                                {/* Text */}
                                <div className="flex-1 min-w-0">
                                    <p className="text-sm font-semibold text-gray-900 truncate">{s.product_name}</p>
                                    <p className="text-xs text-gray-400 truncate">
                                        {s.brand && <span>{s.brand}</span>}
                                        {s.brand && s.category && <span className="mx-1">·</span>}
                                        {s.category && <span>{s.category}</span>}
                                    </p>
                                </div>
                                {/* Price */}
                                {s.price != null && (
                                    <span className="text-sm font-bold text-[#3d5c3a] flex-shrink-0">
                                        ₹{Number(s.price).toLocaleString('en-IN')}
                                    </span>
                                )}
                            </li>
                        ))}
                    </ul>
                    <div className="px-4 py-2.5 border-t border-gray-50 bg-gray-50/50">
                        <button
                            onClick={() => commitSearch(inputValue)}
                            className="w-full text-xs font-semibold text-[#3d5c3a] hover:text-[#2d4a2a] transition-colors cursor-pointer text-center"
                        >
                            See all results for &ldquo;{inputValue}&rdquo; →
                        </button>
                    </div>
                </div>
            )}
        </div>
    );
}

