    sms: { label: 'SMS', description: 'Receive notifications via text message', icon: Smartphone, color: '#2D4A2D' }, // deep herbal-green
    whatsapp: { label: 'WhatsApp', description: 'Receive notifications on WhatsApp', icon: MessageSquare, color: '#25D366' },
    push: { label: 'Push Notifications', description: 'Browser and app push notifications', icon: Bell, color: '#8B7A3D' }, // keeping gold as secondary or shift? user said greenish accents. lets go light green.
};

const CATEGORY_META: Record<string, { label: string; description: string; icon: React.ElementType }> = {
    order_updates: { label: 'Order & Delivery Updates', description: 'Order confirmation, status changes, shipping & delivery', icon: Package },
    account_security: { label: 'Account & Security', description: 'Login alerts, password changes', icon: Shield },
    promotions: { label: 'Promotions & Offers', description: 'Sales, discounts, special deals', icon: Tag },
    price_alerts: { label: 'Price Alerts', description: 'Price drops on wishlist items', icon: TrendingDown },
    newsletter: { label: 'Newsletter', description: 'Weekly curated content & picks', icon: Newspaper },
};

const CATEGORY_ORDER = ['order_updates', 'account_security', 'promotions', 'price_alerts', 'newsletter'];
const CHANNEL_ORDER = ['email', 'sms'];

// SMS channel only shows a subset of categories
const SMS_CATEGORIES = ['order_updates', 'account_security'];

interface NotificationPreferencesProps {
    hideHeader?: boolean;
    isMobileVerified?: boolean;
}

export default function NotificationPreferences({ 
    hideHeader = false,
    isMobileVerified = false 
}: NotificationPreferencesProps) {
    const [preferences, setPreferences] = useState<Preference[]>([]);
    const [loading, setLoading] = useState(true);
    const [togglingKey, setTogglingKey] = useState<string | null>(null);

    const fetchPreferences = useCallback(async () => {
        setLoading(true);
        try {
            const res = await getNotificationPreferences();
            if (res.success && res.data?.preferences) {
                setPreferences(res.data.preferences);
            }
        } catch {
            toast.error('Failed to load notification preferences');
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => {
        fetchPreferences();
    }, [fetchPreferences]);

    const handleToggle = async (channel: string, category: string, currentValue: boolean) => {
        const key = `${channel}:${category}`;
        setTogglingKey(key);

        // Optimistic update
        setPreferences(prev =>
            prev.map(p =>
                p.channel === channel && p.category === category
                    ? { ...p, is_enabled: !currentValue }
                    : p
            )
        );

        try {
            const res = await toggleNotificationPreference(channel, category, !currentValue);
            if (!res.success) {
                // Revert optimistic update
                setPreferences(prev =>
                    prev.map(p =>
                        p.channel === channel && p.category === category
                            ? { ...p, is_enabled: currentValue }
                            : p
                    )
                );
                toast.error(res.message || 'Failed to update preference');
            } else {
                toast.success('Preference updated successfully');
            }
        } catch {
            // Revert
            setPreferences(prev =>
                prev.map(p =>
                    p.channel === channel && p.category === category
                        ? { ...p, is_enabled: currentValue }
                        : p
                )
            );
            toast.error('Network error. Please try again.');
        } finally {
            setTogglingKey(null);
        }
    };

    const getPreferenceValue = (channel: string, category: string): boolean => {
        const pref = preferences.find(p => p.channel === channel && p.category === category);
        return pref?.is_enabled ?? true;
    };

    if (loading) {
        return (
            <div className="flex justify-center py-16">
                <Loader2 className="h-8 w-8 animate-spin text-burgundy" />
            </div>
        );
    }

    return (
        <div className="max-w-3xl space-y-6">
            {/* Header */}
            {!hideHeader && (
                <div>
                    <h2 className="text-lg font-bold text-charcoal">Notification Preferences</h2>
                    <p className="text-sm text-warm-gray mt-0.5">
                        Manage how you&apos;d like to receive alerts and updates from us
                    </p>
                </div>
            )}

            {/* ── Receive Notifications Via ── */}
            <div className="rounded-3xl border border-light-border bg-white overflow-hidden shadow-sm">
                <div className="px-6 py-4 border-b border-light-border bg-cream/50">
                    <h3 className="text-base font-bold text-herbal-green">Receive notifications via:</h3>
                    <p className="text-[10px] font-bold text-warm-gray uppercase tracking-widest mt-1">Select the channels for your periodic awareness</p>
                </div>
                <div className="flex flex-col divide-y divide-light-border/50">
                    {/* SMS — active if verified */}
                    <div className={`flex items-center justify-between px-6 py-4 cursor-default select-none ${!isMobileVerified ? 'opacity-40' : 'bg-cream/20'}`}>
                        <div className="flex items-center gap-3">
                            <span
                                className="relative flex h-5 w-5 items-center justify-center rounded-md border-2"
                                style={{ 
                                    borderColor: isMobileVerified ? '#3B5D3B' : '#D4CFC0', 
                                    backgroundColor: isMobileVerified ? '#3B5D3B' : '#F8F5F0' 
                                }}
                            >
                                {isMobileVerified && (
                                    <svg className="h-3 w-3 text-white" viewBox="0 0 12 12" fill="none">
                                        <path d="M2 6l3 3 5-5" stroke="currentColor" strokeWidth="2.1" strokeLinecap="round" strokeLinejoin="round" />
                                    </svg>
                                )}
                            </span>
                            <div className="flex items-center gap-2">
                                <Smartphone className="h-4 w-4 shrink-0" style={{ color: isMobileVerified ? '#3B5D3B' : '#BDB7A3' }} />
                                <span className="text-sm font-bold text-herbal-green">SMS</span>
                            </div>
                        </div>
                        {isMobileVerified ? (
                            <span className="rounded-full bg-herbal-green/10 px-3 py-1 text-[10px] font-bold uppercase tracking-wider text-herbal-green border border-herbal-green/10">Active</span>
                        ) : (
                            <span className="text-[10px] font-bold uppercase tracking-wider text-warm-gray/60">Unverified</span>
                        )}
                    </div>

                    {/* Email — active */}
                    <div className="flex items-center justify-between px-6 py-4 cursor-default select-none bg-cream/20">
                        <div className="flex items-center gap-3">
                            <span
                                className="relative flex h-5 w-5 items-center justify-center rounded-md border-2"
                                style={{ borderColor: '#3B5D3B', backgroundColor: '#3B5D3B' }}
                            >
                                <svg className="h-3 w-3 text-white" viewBox="0 0 12 12" fill="none">
                                    <path d="M2 6l3 3 5-5" stroke="currentColor" strokeWidth="2.1" strokeLinecap="round" strokeLinejoin="round" />
                                </svg>
                            </span>
                            <div className="flex items-center gap-2">
                                <Mail className="h-4 w-4 shrink-0" style={{ color: '#3B5D3B' }} />
                                <span className="text-sm font-bold text-herbal-green">Email</span>
                            </div>
                        </div>
                        <span className="rounded-full bg-herbal-green/10 px-3 py-1 text-[10px] font-bold uppercase tracking-wider text-herbal-green border border-herbal-green/10">Active</span>
                    </div>

                    {/* WhatsApp — coming soon */}
                    <div className="flex items-center justify-between px-6 py-4 cursor-not-allowed select-none opacity-50">
                        <div className="flex items-center gap-3">
                            <span className="relative flex h-5 w-5 items-center justify-center rounded-md border-2 border-light-border bg-cream/30"></span>
                            <div className="flex items-center gap-2">
                                <MessageSquare className="h-4 w-4 shrink-0 text-warm-gray" />
                                <span className="text-sm font-bold text-warm-gray/80">WhatsApp</span>
                            </div>
                        </div>
                        <span className="rounded-full bg-light-border/40 px-3 py-1 text-[10px] font-bold uppercase tracking-wider text-warm-gray/70">Soon</span>
                    </div>
                </div>
            </div>

            {/* Channel Sections */}
            {CHANNEL_ORDER.map(channel => {
                const meta = CHANNEL_META[channel];
                const Icon = meta.icon;
                // SMS only exposes order_updates + account_security
                const categories = channel === 'sms' ? SMS_CATEGORIES : CATEGORY_ORDER;
                const isChannelDisabled = channel === 'sms' && !isMobileVerified;

                return (
                    <div
                        key={channel}
                        className={`rounded-[32px] border border-light-border bg-white overflow-hidden shadow-sm ${isChannelDisabled ? 'opacity-50 grayscale-[0.8]' : ''}`}
                    >
                        {/* Channel header */}
                        <div className="flex items-center justify-between px-6 py-4 border-b border-light-border bg-cream/50">
                            <div className="flex items-center gap-3">
                                <div
                                    className="flex h-10 w-10 items-center justify-center rounded-xl"
                                    style={{ backgroundColor: isChannelDisabled ? '#F3F4F6' : meta.color + '15' }}
                                >
                                    <Icon className="h-5 w-5" style={{ color: isChannelDisabled ? '#9CA3AF' : meta.color }} />
                                </div>
                                <div>
                                    <h3 className="text-lg font-bold text-herbal-green">{meta.label}</h3>
                                    <p className="text-[11px] font-medium text-warm-gray">{meta.description}</p>
                                </div>
                            </div>
                            {isChannelDisabled && (
                                <div className="text-[9px] font-bold text-burgundy bg-burgundy/5 px-3 py-1.5 rounded-full border border-burgundy/10 uppercase tracking-widest">
                                    Sanctity verification required
                                </div>
                            )}
                        </div>

                        {/* Category toggles */}
                        <div className="divide-y divide-light-border/50">
                            {categories.map(category => {
                                const catMeta = CATEGORY_META[category];
                                const CatIcon = catMeta.icon;
                                const isEnabled = getPreferenceValue(channel, category);
                                const key = `${channel}:${category}`;
                                const isToggling = togglingKey === key;
                                const isInternalDisabled = isChannelDisabled || isToggling;

                                return (
                                    <div
                                        key={category}
                                        className={`flex items-center justify-between px-6 py-3.5 hover:bg-cream/30 transition-colors ${isChannelDisabled ? 'pointer-events-none' : ''}`}
                                    >
                                        <div className="flex items-center gap-4">
                                            <div className="h-8 w-8 rounded-full bg-cream flex items-center justify-center border border-light-border/30">
                                                <CatIcon className="h-4 w-4 text-herbal-green flex-shrink-0" />
                                            </div>
                                            <div>
                                                <p className="text-sm font-bold text-herbal-green tracking-tight">{catMeta.label}</p>
                                                <p className="text-xs text-warm-gray font-medium">{catMeta.description}</p>
                                            </div>
                                        </div>

                                        {/* Toggle */}
                                        <button
                                            onClick={() => !isChannelDisabled && handleToggle(channel, category, isEnabled)}
                                            disabled={isInternalDisabled}
                                            className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors duration-200 focus:outline-none focus:ring-2 focus:ring-offset-2 ${isEnabled && !isChannelDisabled
                                                ? 'focus:ring-burgundy'
                                                : 'focus:ring-gray-300'
                                                } ${isInternalDisabled ? 'opacity-50 cursor-not-allowed' : 'cursor-pointer'}`}
                                            style={{
                                                backgroundColor: isEnabled && !isChannelDisabled ? meta.color : '#D1D5DB',
                                            }}
                                            aria-label={`${isEnabled ? 'Disable' : 'Enable'} ${catMeta.label} via ${meta.label}`}
                                        >
                                            <span
                                                className={`inline-block h-4 w-4 transform rounded-full bg-white shadow-sm transition-transform duration-200 ${(isEnabled && !isChannelDisabled) ? 'translate-x-6' : 'translate-x-1'
                                                    }`}
                                            />
                                        </button>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                );
            })}
            {/* Footer info */}
            <div className="rounded-xl bg-cream/60 border border-light-border px-5 py-4">
                <p className="text-xs text-warm-gray leading-relaxed">
                    <strong className="text-charcoal">Note:</strong> Account security notifications (login alerts, password changes) are always
                    sent via email for your safety and cannot be fully disabled. SMS notifications require a verified phone number on your account.
                </p>
            </div>
        </div>
    );
}

'use client';
import { authFetch, API_URL } from '@/lib/api';

import { useState, useEffect } from 'react';
import { Shield, Download, Trash2, Eye, ExternalLink, Loader2, Info } from 'lucide-react';
import toast from 'react-hot-toast';

export default function PrivacyDashboard() {
    const [loading, setLoading] = useState(false);
    const [requests, setRequests] = useState<any[]>([]);

    useEffect(() => {
        fetchRequests();
    }, []);

    const fetchRequests = async () => {
        try {
            const res = await authFetch(`${API_URL}/api/gdpr/data-request`);
            if (res.ok) {
                const data = await res.json();
                if (data.success) {
                    setRequests(data.data);
                }
            }
        } catch (error) {
            console.error('Failed to fetch requests', error);
        }
    };

    const handleExport = async () => {
        setLoading(true);
        try {
            const res = await authFetch(`${API_URL}/api/gdpr/export`);
            if (res.ok) {
                const data = await res.json();
                if (data.success) {
                    const blob = new Blob([JSON.stringify(data.data, null, 2)], { type: 'application/json' });
                    const url = window.URL.createObjectURL(blob);
                    const a = document.createElement('a');
                    a.href = url;
                    a.download = `my-data-export-${new Date().toISOString().split('T')[0]}.json`;
                    a.click();
                    toast.success('Data exported successfully.');
                    fetchRequests(); // refresh logs
                } else {
                    toast.error(data.message || 'Export failed.');
                }
            }
        } catch (error) {
            toast.error('Network error during export.');
        } finally {
            setLoading(false);
        }
    };

    const handleErasure = async () => {
        if (!confirm('WARNING: This action is irreversible. It will completely anonymize your personal data and delete your account. Are you absolutely sure?')) {
            return;
        }

        setLoading(true);
        try {
            const res = await authFetch(`${API_URL}/api/gdpr/erasure`, {
                method: 'DELETE'
            });
            if (res.ok) {
                const data = await res.json();
                if (data.success) {
                    toast.success('Account successfully erased.');
                    window.location.href = '/login'; // log out natively
                } else {
                    toast.error(data.message || 'Erasure failed.');
                }
            }
        } catch (error) {
            toast.error('Network error during erasure request.');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="space-y-6 max-w-3xl">
            <div className="flex items-center gap-3 border-b border-light-border pb-4">
                <Shield className="h-6 w-6 text-burgundy" />
                <div>
                    <h2 className="text-xl font-bold text-charcoal">Privacy & Data Management</h2>
                    <p className="text-sm text-warm-gray">Control your personal data in compliance with GDPR guidelines.</p>
                </div>
            </div>

            {/* General Privacy Center Info */}
            <div className="bg-emerald-50 border border-emerald-100 rounded-xl p-5 text-emerald-900 text-sm flex gap-3">
                <Info className="h-5 w-5 shrink-0 text-emerald-600 mt-0.5" />
                <div>
                    <p className="font-semibold mb-1 text-emerald-800">Your Data Subjects Rights</p>
                    <p className="leading-relaxed opacity-90">
                        Under the General Data Protection Regulation (GDPR), you have the right to access, rectify, port, and erase your personal information.
                        Use the tools below to execute these rights automatically.
                    </p>
                    <a href="/privacy-policy" className="inline-flex items-center gap-1 mt-2 text-emerald-700 font-medium hover:underline">
                        Read our Privacy Policy <ExternalLink className="h-3 w-3" />
                    </a>
                </div>
            </div>

            <div className="grid md:grid-cols-2 gap-4">
                {/* Data Export Card */}
                <div className="rounded-xl border border-light-border bg-white p-5 hover:shadow-md transition-shadow">
                    <div className="flex h-10 w-10 items-center justify-center rounded-full bg-blue-50 mb-4">
                        <Download className="h-5 w-5 text-blue-600" />
                    </div>
                    <h3 className="font-bold text-charcoal mb-1">Data Portability</h3>
                    <p className="text-sm text-warm-gray mb-4">Download a machine-readable JSON file containing all your personal data, orders, and addresses.</p>
                    <button
                        onClick={handleExport}
                        disabled={loading}
                        className="w-full flex justify-center items-center gap-2 rounded-lg border border-light-border px-4 py-2 text-sm font-semibold text-charcoal hover:bg-cream transition-colors disabled:opacity-50"
                    >
                        {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : <Download className="h-4 w-4" />}
                        Export My Data
                    </button>
                </div>

                {/* Data Erasure Card */}
                <div className="rounded-xl border border-light-border bg-white p-5 hover:border-red-200 transition-colors">
                    <div className="flex h-10 w-10 items-center justify-center rounded-full bg-red-50 mb-4">
                        <Trash2 className="h-5 w-5 text-red-600" />
                    </div>
                    <h3 className="font-bold text-charcoal mb-1">Right to be Forgotten</h3>
                    <p className="text-sm text-warm-gray mb-4">Permanently anonymize your personal information. This action will delete your account instantly.</p>
                    <button
                        onClick={handleErasure}
                        disabled={loading}
                        className="w-full flex justify-center items-center gap-2 rounded-lg bg-red-50 text-red-600 hover:bg-red-100 border border-red-100 px-4 py-2 text-sm font-semibold transition-colors disabled:opacity-50"
                    >
                        {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : <Trash2 className="h-4 w-4" />}
                        Erase Personal Data
                    </button>
                </div>
            </div>

            {/* Request History Log */}
            <div className="rounded-xl border border-light-border bg-white overflow-hidden mt-8">
                <div className="bg-cream px-5 py-3 border-b border-light-border flex justify-between items-center">
                    <h3 className="font-bold text-charcoal">Data Request Log</h3>
                    <div className="text-xs text-warm-gray">Maintained for Article 30 compliance</div>
                </div>
                {requests.length === 0 ? (
                    <div className="p-8 text-center text-warm-gray text-sm">
                        No previous privacy requests found.
                    </div>
                ) : (
                    <ul className="divide-y divide-light-border">
                        {requests.map(req => (
                            <li key={req.id} className="p-4 flex items-center justify-between text-sm hover:bg-gray-50/50">
                                <div>
                                    <p className="font-medium text-charcoal">{req.request_type}</p>
                                    <p className="text-xs text-warm-gray mt-0.5">{new Date(req.created_at).toLocaleString()}</p>
                                    {req.details && <p className="text-xs text-warm-gray italic mt-1 bg-gray-50 p-1 inline-block rounded border">"{req.details}"</p>}
                                </div>
                                <span className={`px-2.5 py-1 rounded-full text-xs font-semibold ${req.status === 'COMPLETED' ? 'bg-emerald-100 text-emerald-700' :
                                    req.status === 'REJECTED' ? 'bg-red-100 text-red-700' :
                                        'bg-amber-100 text-amber-700'
                                    }`}>
                                    {req.status}
                                </span>
                            </li>
                        ))}
                    </ul>
                )}
            </div>

        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import Image from 'next/image';

interface ButterflyInstance {
  id: number;
  startX: number;
  startY: number;
  endX: number;
  endY: number;
}

// ─── Main Butterfly Component ───
export default function ButterflyEffect() {
  const [butterflies, setButterflies] = useState<ButterflyInstance[]>([]);
  const [cartTarget, setCartTarget] = useState({ x: 0, y: 0 });

  // Continuously track cart position for any active butterflies to land accurately
  useEffect(() => {
    const updateCartTarget = () => {
      const cartIcon = document.getElementById('navbar-cart-icon');
      if (cartIcon) {
        const rect = cartIcon.getBoundingClientRect();
        const svg = cartIcon.querySelector('svg');
        if (svg) {
          const sRect = svg.getBoundingClientRect();
          setCartTarget({
            x: sRect.left + sRect.width / 2,
            y: sRect.top + sRect.height / 2 - 15 // Sit slightly on TOP of the icon
          });
        } else {
          setCartTarget({
            x: rect.left + rect.width / 2,
            y: rect.top + rect.height / 2 - 15
          });
        }
      }
    };

    updateCartTarget();
    window.addEventListener('resize', updateCartTarget);
    window.addEventListener('scroll', updateCartTarget, true);
    return () => {
      window.removeEventListener('resize', updateCartTarget);
      window.removeEventListener('scroll', updateCartTarget, true);
    };
  }, []);

  useEffect(() => {
    const handleTrigger = (event: any) => {
      const { startX, startY } = event.detail;
      setButterflies(prev => [...prev, {
        id: Date.now() + Math.random(),
        startX,
        startY,
        endX: cartTarget.x,
        endY: cartTarget.y,
      }]);
    };

    window.addEventListener('add-to-cart-butterfly', handleTrigger);
    return () => window.removeEventListener('add-to-cart-butterfly', handleTrigger);
  }, [cartTarget]);

  return (
    <div className="fixed inset-0 pointer-events-none" style={{ zIndex: 2147483647 }}>
      <AnimatePresence>
        {butterflies.map(b => (
          <motion.div
            key={b.id}
            initial={{
              x: b.startX - 40,
              y: b.startY - 40,
              scale: 0.2,
              opacity: 1,
              rotateZ: 0,
            }}
            animate={{
              // Majestic organic path - using current cartTarget for dynamic landing
              x: [
                b.startX - 40, 
                b.startX - 100, 
                b.startX + 100, 
                cartTarget.x + 20, 
                cartTarget.x - 40,
                cartTarget.x - 40
              ],
              y: [
                b.startY - 40, 
                b.startY - 250, 
                b.startY - 450, 
                cartTarget.y - 60, 
                cartTarget.y - 40,
                cartTarget.y - 40
              ],
              scale: [0.2, 1.5, 1.2, 0.8, 0.4, 0],
              opacity: [1, 1, 1, 1, 1, 0],
              rotateZ: [0, -25, 35, -15, 0, 0],
            }}
            transition={{
              duration: 6.5,
              ease: "easeInOut",
              times: [0, 0.2, 0.5, 0.8, 0.92, 1] 
            }}
            onAnimationComplete={() => setButterflies(prev => prev.filter(item => item.id !== b.id))}
            className="absolute w-[80px] h-[80px]"
          >
            <div className="relative w-full h-full flex items-center justify-center" style={{ perspective: '1000px', transformStyle: 'preserve-3d' }}>
              {/* Left Wing */}
              <motion.div
                className="absolute w-full h-full origin-center"
                style={{ clipPath: 'inset(0 50% 0 0)' }}
                animate={{ 
                  rotateY: [0, -80, 0, -80, 0, -20, 0, -50, 0, -50, 0] 
                }}
                transition={{ 
                  duration: 2.8, 
                  repeat: Infinity, 
                  ease: "easeInOut",
                  times: [0, 0.08, 0.16, 0.24, 0.32, 0.5, 0.7, 0.8, 0.85, 0.9, 1]
                }}
              >
                <div className="relative w-full h-full">
                  <Image
                    src="/botanical-butterfly1.png"
                    alt=""
                    fill
                    sizes="80px"
                    className="object-contain"
                    priority
                  />
                </div>
              </motion.div>

              {/* Right Wing */}
              <motion.div
                className="absolute w-full h-full origin-center"
                style={{ clipPath: 'inset(0 0 0 50%)' }}
                animate={{ 
                  rotateY: [0, 80, 0, 80, 0, 20, 0, 50, 0, 50, 0] 
                }}
                transition={{ 
                  duration: 2.8, 
                  repeat: Infinity, 
                  ease: "easeInOut",
                  times: [0, 0.08, 0.16, 0.24, 0.32, 0.5, 0.7, 0.8, 0.85, 0.9, 1]
                }}
              >
                <div className="relative w-full h-full">
                  <Image
                    src="/botanical-butterfly1.png"
                    alt=""
                    fill
                    sizes="80px"
                    className="object-contain"
                    priority
                  />
                </div>
              </motion.div>

              {/* Magical Botanical Aura */}
              <motion.div
                className="absolute inset-0 bg-[#3B5D3B]/10 blur-2xl rounded-full -z-10"
                animate={{ 
                  scale: [1, 2.5, 1], 
                  opacity: [0.2, 0.5, 0.2]
                }}
                transition={{ duration: 4, repeat: Infinity }}
              />
            </div>
          </motion.div>
        ))}
      </AnimatePresence>
    </div>
  );
}

