'use client';

import { useState, useCallback, useMemo, useRef, useEffect, memo } from 'react';
import Image from 'next/image';
import type { ProductAsset, GalleryImage } from '@/types';
import ImageThumbnailStrip from './ImageThumbnailStrip';
import ImageZoom from './ImageZoom';
import ImageLightbox from './ImageLightbox';
import styles from './gallery.module.css';

interface ProductImageGalleryProps {
    assets?: ProductAsset[];
    productName: string;
    variantId?: string;
    defaultVariantId?: string;
    /** Fallback image URLs from product.images (thumbnail_url mapped) */
    fallbackImages?: string[];
    brand?: string;
    category?: string;
}

const FALLBACK_IMAGE = '/herbal_placeholder.png';

/**
 * Resolve ProductAsset[] → GalleryImage[]
 * Robust: handles pre-migration data, missing fields, and all src formats.
 * Falls back to `fallbackImages` (e.g. from thumbnail_url) when assets are empty.
 */
function resolveGalleryImages(
    assets: ProductAsset[] | undefined,
    productName: string,
    variantId?: string,
    defaultVariantId?: string,
    fallbackImages?: string[],
    brand?: string,
    category?: string
): GalleryImage[] {
    if (assets && Array.isArray(assets) && assets.length > 0) {
        const getAssetsForVid = (vid: string | undefined | null) => assets.filter((a) => {
            const targetVid = String(vid || '').toLowerCase() || null;
            const assetVid = String(a.variant_id || '').toLowerCase() || null;
            return assetVid === targetVid;
        });

        // 1. Collect assets from relevant levels
        const variantAssets = getAssetsForVid(variantId);
        const productLevelAssets = getAssetsForVid(null);
        
        // Use a Map for de-duplication by asset_id or unique identifier
        const assetsMap = new Map<string, typeof assets[0]>();
        
        // Add variant-specific assets first
        variantAssets.forEach(a => assetsMap.set(a.asset_id || a.cdn_url || a.asset_url || a.base64_data || '', a));
        
        // Add product-level (shared) assets
        productLevelAssets.forEach(a => {
            const key = a.asset_id || a.cdn_url || a.asset_url || a.base64_data || '';
            if (!assetsMap.has(key)) assetsMap.set(key, a);
        });
        
        // 2. Special Fallback: If current set is strictly empty, pull in Default Variant assets
        if (assetsMap.size === 0 && defaultVariantId && variantId !== defaultVariantId) {
            getAssetsForVid(defaultVariantId).forEach(a => {
                assetsMap.set(a.asset_id || a.cdn_url || a.asset_url || a.base64_data || '', a);
            });
        }

        // 3. Critical Video Fallback: If no videos in current pool, check Default Variant
        const currentHasVideo = Array.from(assetsMap.values()).some(a => a.media_type === 'video');
        if (!currentHasVideo && defaultVariantId && variantId !== defaultVariantId) {
            getAssetsForVid(defaultVariantId).filter(a => a.media_type === 'video').forEach(a => {
                assetsMap.set(a.asset_id || a.cdn_url || a.asset_url || a.base64_data || '', a);
            });
        }

        // Sort: Primary first, then by sort_order
        const unique = Array.from(assetsMap.values()).sort((a, b) => {
            if (a.is_primary && !b.is_primary) return -1;
            if (!a.is_primary && b.is_primary) return 1;
            return (a.sort_order || 0) - (b.sort_order || 0);
        });

        const gallery: GalleryImage[] = [];

        // Image assets
        unique.filter((a) => a.media_type !== 'video' || !a.media_type).forEach((a, index) => {
            let src = a.cdn_url || a.asset_url || a.base64_data;
            if (!src && fallbackImages && fallbackImages.length > 0) {
                src = fallbackImages[0];
            }

            let enrichedAlt = a.alt_text;
            if (!enrichedAlt) {
                const parts = [];
                if (brand) parts.push(brand);
                parts.push(productName);
                if (category) parts.push(category);
                enrichedAlt = `${parts.join(' ')} - Image ${index + 1}`;
            }

            gallery.push({
                id: a.asset_id || `asset-${index}`,
                src: src || FALLBACK_IMAGE,
                alt: enrichedAlt,
                width: a.width,
                height: a.height,
                blurhash: a.blurhash,
                imageType: a.image_type,
                isPrimary: a.is_primary,
            });
        });

        // Video assets
        unique.filter((a) => a.media_type === 'video').forEach((a, index) => {
            const videoUrl = a.cdn_url || a.asset_url || a.base64_data || '';
            const enrichedAlt = a.alt_text || `${productName} Video ${index + 1}`;

            gallery.push({
                id: a.asset_id || `video-${index}`,
                src: FALLBACK_IMAGE,
                alt: enrichedAlt,
                isVideo: true,
                videoSrc: videoUrl,
            });
        });

        if (gallery.length > 0) return gallery;
    }

    // Fallback: use product.images (populated from thumbnail_url)
    if (fallbackImages && fallbackImages.length > 0) {
        const validFallbacks = fallbackImages.filter((src) => !!src);
        if (validFallbacks.length > 0) {
            return validFallbacks.map((src, index) => ({
                id: `fallback-${index}`,
                src,
                alt: `${productName} - Image ${index + 1}`,
                isPrimary: index === 0,
            }));
        }
    }

    return [
        {
            id: 'default-fallback',
            src: FALLBACK_IMAGE,
            alt: `${productName} - Product Image`,
            isPrimary: true,
        },
    ];
}

/**
 * ProductImageGallery — Amazon-Style with video support inline
 */
function ProductImageGalleryInner({
    assets,
    productName,
    variantId,
    defaultVariantId,
    fallbackImages,
    brand,
    category
}: ProductImageGalleryProps) {
    const [activeIndex, setActiveIndex] = useState(0);
    const [lightboxOpen, setLightboxOpen] = useState(false);
    const [imageLoaded, setImageLoaded] = useState(false);
    const [imageError, setImageError] = useState(false);

    // Refs for Amazon-style zoom
    const mainPreviewRef = useRef<HTMLDivElement>(null);
    const zoomPanelRef = useRef<HTMLDivElement>(null);
    const imageRef = useRef<HTMLImageElement>(null);

    const images = useMemo(
        () => resolveGalleryImages(assets, productName, variantId, defaultVariantId, fallbackImages, brand, category),
        [assets, productName, variantId, defaultVariantId, fallbackImages, brand, category]
    );

    useEffect(() => {
        setActiveIndex(0);
        setImageLoaded(false);
        setImageError(false);
    }, [variantId, images.length]);

    useEffect(() => {
        setImageLoaded(false);
        setImageError(false);
    }, [activeIndex]);

    // Keyboard nav (when lightbox is closed)
    useEffect(() => {
        const handleKey = (e: KeyboardEvent) => {
            if (lightboxOpen) return;
            if (e.key === 'ArrowLeft') setActiveIndex((p) => (p > 0 ? p - 1 : images.length - 1));
            if (e.key === 'ArrowRight') setActiveIndex((p) => (p < images.length - 1 ? p + 1 : 0));
        };
        document.addEventListener('keydown', handleKey);
        return () => document.removeEventListener('keydown', handleKey);
    }, [images.length, lightboxOpen]);

    // Hydration fix: Base64 dataURIs load so fast they often finish before React attaches onLoad
    useEffect(() => {
        if (imageRef.current?.complete && !imageLoaded) {
            // eslint-disable-next-line react-hooks/set-state-in-effect
            setImageLoaded(true);
        }
    }, [activeIndex, images, imageLoaded]);

    const handleThumbnailSelect = useCallback((i: number) => setActiveIndex(i), []);
    const handleThumbnailHover = useCallback((i: number) => setActiveIndex(i), []);
    const openLightbox = useCallback(() => { if (images.length > 0) setLightboxOpen(true); }, [images.length]);
    const closeLightbox = useCallback(() => setLightboxOpen(false), []);
    const lightboxPrev = useCallback(() => setActiveIndex((p) => (p > 0 ? p - 1 : images.length - 1)), [images.length]);
    const lightboxNext = useCallback(() => setActiveIndex((p) => (p < images.length - 1 ? p + 1 : 0)), [images.length]);
    const handleImageLoad = useCallback(() => setImageLoaded(true), []);
    const handleImageError = useCallback(() => { setImageError(true); setImageLoaded(true); }, []);

    const currentImage = images[activeIndex] || images[0];
    const displaySrc = imageError ? FALLBACK_IMAGE : currentImage.src;

    return (
        <>
            <div
                className={styles.galleryContainer}
                role="region"
                aria-label="Product image gallery"
            >
                {/* Thumbnail strip */}
                <ImageThumbnailStrip
                    images={images}
                    activeIndex={activeIndex}
                    onSelect={handleThumbnailSelect}
                    onHover={handleThumbnailHover}
                />

                {/* Main preview area — contains preview + zoom panel side by side */}
                <div className={styles.previewZoomRow}>
                    {/* Main image (overflow:hidden for rounded corners) */}
                    <div
                        ref={mainPreviewRef}
                        className={styles.mainPreviewWrapper}
                        onClick={currentImage.isVideo ? undefined : openLightbox}
                    >
                        {!imageLoaded && !currentImage.isVideo && <div className={styles.skeleton} />}

                        {currentImage.isVideo ? (
                            <video
                                key={currentImage.id}
                                src={currentImage.videoSrc}
                                controls
                                autoPlay
                                loop
                                muted
                                playsInline
                                preload="metadata"
                                className={`${styles.mainImage} ${styles.loaded}`}
                                style={{ objectFit: 'contain', background: '#000' }}
                            >
                                Your browser does not support the video tag.
                            </video>
                        ) : (
                            <Image
                                ref={imageRef}
                                key={currentImage.id}
                                src={displaySrc}
                                alt={currentImage.alt}
                                fill
                                className={`${styles.mainImage} ${imageLoaded ? styles.loaded : styles.loading}`}
                                onLoad={handleImageLoad}
                                onError={handleImageError}
                                draggable={false}
                                priority
                                sizes="(max-width: 1024px) 100vw, 50vw"
                                style={{ objectFit: 'contain' }}
                            />
                        )}

                        {/* Image counter */}
                        {images.length > 1 && (
                            <div className={styles.imageCounter}>
                                <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                                    <rect x="3" y="3" width="18" height="18" rx="2" />
                                    <circle cx="8.5" cy="8.5" r="1.5" />
                                    <path d="M21 15l-5-5L5 21" />
                                </svg>
                                {activeIndex + 1} / {images.length}
                            </div>
                        )}

                        {/* Expand icon — only for images */}
                        {!currentImage.isVideo && (
                            <div className={styles.expandIcon}>
                                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                                    <path d="M15 3h6v6M9 21H3v-6M21 3l-7 7M3 21l7-7" />
                                </svg>
                            </div>
                        )}
                    </div>

                    {/* Zoom panel — OUTSIDE overflow:hidden, positioned by CSS */}
                    <div
                        ref={zoomPanelRef}
                        className={styles.zoomPanel}
                        role="img"
                        aria-label={`Zoomed view: ${currentImage.alt}`}
                    />
                </div>

                {/* Headless zoom controller — attaches listeners to imageRef, writes to zoomPanelRef */}
                <ImageZoom
                    src={displaySrc}
                    alt={currentImage.alt}
                    isActive={imageLoaded && !imageError}
                    imageRef={imageRef}
                    panelRef={zoomPanelRef}
                />
            </div>

            {/* Lightbox */}
            {lightboxOpen && (
                <ImageLightbox
                    images={images}
                    activeIndex={activeIndex}
                    onClose={closeLightbox}
                    onPrev={lightboxPrev}
                    onNext={lightboxNext}
                    onSelect={handleThumbnailSelect}
                />
            )}

        </>
    );
}

const ProductImageGallery = memo(ProductImageGalleryInner);
export default ProductImageGallery;

'use client';

import { useState, useRef } from 'react';
import { Play } from 'lucide-react';

interface LazyVideoProps {
    /** Video source URL */
    src: string;
    /** Poster image URL */
    poster?: string;
    /** Alt text / title */
    title?: string;
    /** CSS class for the container */
    className?: string;
    /** Width of the video */
    width?: number;
    /** Height of the video */
    height?: number;
}

/**
 * Video component that does NOT preload.
 * Shows a poster image with a play button overlay.
 * Loads and plays the actual video only when the user clicks play.
 */
export default function LazyVideo({
    src,
    poster,
    title,
    className = '',
    width,
    height,
}: LazyVideoProps) {
    const [isPlaying, setIsPlaying] = useState(false);
    const videoRef = useRef<HTMLVideoElement>(null);

    const handlePlay = () => {
        setIsPlaying(true);
        // Wait for next tick so the video element mounts
        setTimeout(() => {
            videoRef.current?.play();
        }, 0);
    };

    return (
        <div
            className={`relative overflow-hidden bg-black ${className}`}
            style={{ aspectRatio: width && height ? `${width}/${height}` : '16/9' }}
        >
            {!isPlaying ? (
                /* Poster + Play button */
                <button
                    onClick={handlePlay}
                    className="relative w-full h-full group cursor-pointer"
                    aria-label={`Play video: ${title || 'Product video'}`}
                >
                    {poster ? (
                        <img
                            src={poster}
                            alt={title || 'Video thumbnail'}
                            className="w-full h-full object-cover"
                            loading="lazy"
                        />
                    ) : (
                        <div className="w-full h-full bg-neutral-900 flex items-center justify-center">
                            <span className="text-neutral-500 text-sm">Video</span>
                        </div>
                    )}
                    {/* Play overlay */}
                    <div className="absolute inset-0 flex items-center justify-center bg-black/30 group-hover:bg-black/40 transition-colors">
                        <div className="flex items-center justify-center w-16 h-16 rounded-full bg-white/90 shadow-lg group-hover:scale-110 transition-transform">
                            <Play className="h-7 w-7 text-burgundy ml-1" fill="currentColor" />
                        </div>
                    </div>
                </button>
            ) : (
                /* Actual video (loaded on demand) */
                <video
                    ref={videoRef}
                    src={src}
                    poster={poster}
                    controls
                    preload="none"
                    className="w-full h-full object-contain"
                    title={title}
                >
                    Your browser does not support the video tag.
                </video>
            )}
        </div>
    );
}

'use client';

import StarRating from './StarRating';
import { ThumbsUp, ThumbsDown, BadgeCheck, Flag, CornerDownRight } from 'lucide-react';
import { voteHelpful, reportReview } from '@/lib/api';
import { useState } from 'react';
import toast from 'react-hot-toast';

export interface Review {
    review_id: string;
    rating: number;
    title?: string;
    body?: string;
    reviewer_name: string;
    is_verified_purchase?: boolean;
    helpful_count?: number;
    admin_reply?: string;
    admin_reply_at?: string;
    created_at: string;
    own_vote?: 'up' | 'down' | null;
    has_reported?: boolean;
}

interface ReviewCardProps {
    review: Review;
}

export default function ReviewCard({ review }: ReviewCardProps) {
    const [helpfulCount, setHelpfulCount] = useState(review.helpful_count ?? 0);
    const [voteStatus, setVoteStatus] = useState<'none' | 'up' | 'down'>(review.own_vote || 'none');

    // Reporting state
    const [isReporting, setIsReporting] = useState(false);
    const [reportReason, setReportReason] = useState('');
    const [isSubmittingReport, setIsSubmittingReport] = useState(false);
    const [hasReported, setHasReported] = useState(!!review.has_reported);

    const handleVote = async (type: 'up' | 'down') => {
        if (voteStatus === type) return; // Prevent double voting the same way

        // Optimistic UI update
        const previousVote = voteStatus;
        const previousCount = helpfulCount;

        setVoteStatus(type);
        if (type === 'up') {
            setHelpfulCount(c => c + (previousVote === 'down' ? 2 : 1));
        } else {
            setHelpfulCount(c => c - (previousVote === 'up' ? 2 : 1));
        }

        try {
            const res = await voteHelpful(review.review_id, type);
            if (!res || res.success === false) {
                toast.error(res?.message || 'Failed to register vote. Please log in.');
                setVoteStatus(previousVote);
                setHelpfulCount(previousCount);
            }
        } catch (error) {
            // Revert on network error
            toast.error('Network error. Please try again.');
            setVoteStatus(previousVote);
            setHelpfulCount(previousCount);
        }
    };

    const handleReport = async () => {
        if (!reportReason.trim()) {
            toast.error('Please provide a reason for reporting.');
            return;
        }

        setIsSubmittingReport(true);
        try {
            const res = await reportReview(review.review_id, reportReason);
            if (res && res.success === false) {
                toast.error(res.message || 'Failed to submit report. Ensure you are logged in.');
            } else {
                toast.success('Review reported successfully.');
                setHasReported(true);
                setIsReporting(false);
            }
        } catch (error) {
            toast.error('Network error. Please try again.');
        } finally {
            setIsSubmittingReport(false);
        }
    };

    const dateStr = new Date(review.created_at).toLocaleDateString('en-US', {
        year: 'numeric',
        month: 'short',
        day: 'numeric',
    });

    return (
        <div className="bg-white p-6 rounded-2xl shadow-[0_4px_24px_rgba(0,0,0,0.04)] group mb-4">
            {/* Header */}
            <div className="flex items-center justify-between gap-4 mb-4">
                <StarRating value={review.rating} size="sm" />
                <span className="text-xs font-semibold text-gray-400 uppercase tracking-widest">{dateStr}</span>
            </div>

            {/* Body */}
            {review.body && (
                <p className="text-[15px] font-medium text-gray-800 leading-relaxed italic">
                    "{review.body}"
                </p>
            )}

            {/* Admin Reply */}
            {review.admin_reply && (
                <div className="mt-4 ml-4 bg-[#3d5c3a]/5 p-4 rounded-xl border-l-2 border-[#3d5c3a]">
                    <div className="flex items-center gap-2 mb-1">
                        <CornerDownRight size={14} className="text-[#3d5c3a]" />
                        <span className="text-xs font-bold uppercase tracking-wider text-[#3d5c3a]">Vedashi Response</span>
                        {review.admin_reply_at && (
                            <span className="text-xs text-gray-500 font-medium ml-1">
                                {new Date(review.admin_reply_at).toLocaleDateString('en-US', {
                                    month: 'short', day: 'numeric', year: 'numeric'
                                })}
                            </span>
                        )}
                    </div>
                    <p className="text-[14px] text-gray-600 ml-5 leading-relaxed">
                        {review.admin_reply}
                    </p>
                </div>
            )}

            {/* Footer */}
            <div className="mt-6 flex items-center justify-between gap-4 pt-4 border-t border-gray-100">
                <div className="flex items-center gap-3">
                    <div className="h-8 w-8 rounded-full bg-[#3d5c3a] text-white flex items-center justify-center text-xs font-bold shadow-sm">
                        {review.reviewer_name.charAt(0).toUpperCase()}
                    </div>
                    <div>
                        <span className="block text-sm font-bold text-gray-900">{review.reviewer_name}</span>
                        {review.is_verified_purchase && (
                            <span className="flex items-center gap-1 text-[10px] text-gray-500 font-medium">
                                <BadgeCheck size={12} className="text-[#3d5c3a]" />
                                Verified Purchase
                            </span>
                        )}
                    </div>
                </div>

                <div className="ml-auto flex items-center gap-3">
                    {/* Helpful up/down votes */}
                    <div className="flex items-center gap-2 bg-neutral-50 px-2.5 py-1 rounded-full border border-neutral-100">
                        <button
                            onClick={() => handleVote('up')}
                            className={`flex items-center transition-colors hover:text-[#C5A46D] ${voteStatus === 'up' ? 'text-[#C5A46D]' : ''}`}
                            aria-label="Upvote review"
                        >
                            <ThumbsUp size={14} className={voteStatus === 'up' ? 'fill-current' : ''} />
                            <span className="ml-1.5 min-w-[12px] text-center font-medium text-neutral-500">
                                {helpfulCount > 0 ? helpfulCount : 0}
                            </span>
                        </button>
                        <div className="w-[1px] h-3 bg-neutral-200"></div>
                        <button
                            onClick={() => handleVote('down')}
                            className={`flex items-center transition-colors hover:text-red-500 ${voteStatus === 'down' ? 'text-red-500' : ''}`}
                            aria-label="Downvote review"
                        >
                            <ThumbsDown size={14} className={voteStatus === 'down' ? 'fill-current' : ''} />
                        </button>
                    </div>

                    {/* Report button */}
                    <button
                        onClick={() => setIsReporting(!isReporting)}
                        className={`flex items-center gap-1 transition-colors ${isReporting || hasReported ? 'text-red-500' : 'text-neutral-400 hover:text-red-500'}`}
                        title="Report this review"
                        disabled={hasReported}
                    >
                        <Flag size={13} className={hasReported ? "text-red-400" : ""} />
                        <span className="text-xs font-medium">{hasReported ? 'Reported' : 'Report'}</span>
                    </button>
                </div>
            </div>

            {/* Report Form */}
            {isReporting && !hasReported && (
                <div className="mt-3 p-3 bg-red-50 border border-red-100 rounded-md text-sm">
                    <p className="font-medium text-red-800 mb-2">Report Review</p>
                    <textarea
                        value={reportReason}
                        onChange={(e) => setReportReason(e.target.value)}
                        placeholder="Why are you reporting this review? (e.g. harmful language, spam)"
                        className="w-full text-sm border-gray-200 rounded p-2 mb-2 resize-none focus:ring-red-500 focus:border-red-500 bg-white"
                        rows={2}
                    />
                    <div className="flex justify-end gap-2">
                        <button
                            onClick={() => setIsReporting(false)}
                            className="px-3 py-1.5 text-xs font-medium text-neutral-600 hover:bg-neutral-100 rounded transition-colors"
                        >
                            Cancel
                        </button>
                        <button
                            onClick={handleReport}
                            disabled={isSubmittingReport || !reportReason.trim()}
                            className="px-3 py-1.5 text-xs font-medium bg-red-600 text-white rounded hover:bg-red-700 disabled:opacity-50 transition-colors"
                        >
                            {isSubmittingReport ? 'Submitting...' : 'Submit Report'}
                        </button>
                    </div>
                </div>
            )}
        </div>
    );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import StarRating from './StarRating';
import ReviewCard from './ReviewCard';
import ReviewForm from './ReviewForm';
import { getProductReviews, getRatingSummary, getMyReviewForProduct } from '@/lib/api';
import { useAuth } from '@/context/AuthContext';
import { MessageSquare } from 'lucide-react';

interface RatingSummary {
    total_reviews: number;
    average_rating: number;
    distribution: Record<number, number>;
}

interface Review {
    review_id: string;
    rating: number;
    title?: string;
    body?: string;
    reviewer_name: string;
    is_verified_purchase?: boolean;
    helpful_count?: number;
    created_at: string;
    own_vote?: 'up' | 'down' | null;
    has_reported?: boolean;
}

interface ReviewSectionProps {
    productId: string;
    product?: any;
    selectedVariant?: any;
    onAddToCart?: (e: React.MouseEvent<HTMLButtonElement>) => void;
}

const SORT_OPTIONS = [
    { label: 'Most Recent', value: 'recent' },
    { label: 'Most Helpful', value: 'helpful' },
    { label: 'Highest Rated', value: 'highest' },
    { label: 'Lowest Rated', value: 'lowest' },
];

export default function ReviewSection({ productId, product, selectedVariant, onAddToCart }: ReviewSectionProps) {
    const { isAuthenticated } = useAuth();

    const [summary, setSummary] = useState<RatingSummary | null>(null);
    const [reviews, setReviews] = useState<Review[]>([]);
    const [myReview, setMyReview] = useState<Review | null>(null);
    const [sort, setSort] = useState('recent');
    const [loading, setLoading] = useState(true);

    const fetchData = useCallback(async () => {
        setLoading(true);
        try {
            const [reviewsRes, summaryRes] = await Promise.all([
                getProductReviews(productId, { sort, limit: 50 }),
                getRatingSummary(productId),
            ]);

            if (reviewsRes.success && reviewsRes.data) {
                setReviews(reviewsRes.data.reviews ?? reviewsRes.data ?? []);
                if (reviewsRes.data.summary) {
                    setSummary(reviewsRes.data.summary);
                }
            }
            if (summaryRes.success && summaryRes.data) {
                setSummary(summaryRes.data);
            }

            // Check if user has an existing review
            if (isAuthenticated) {
                try {
                    const myRes = await getMyReviewForProduct(productId);
                    if (myRes.success && myRes.data?.has_reviewed) {
                        setMyReview(myRes.data.review);
                    } else {
                        setMyReview(null);
                    }
                } catch { setMyReview(null); }
            }
        } catch (err) {
            console.error('[Reviews] Failed to fetch:', err);
        } finally {
            setLoading(false);
        }
    }, [productId, sort, isAuthenticated]);

    useEffect(() => {
        fetchData();
    }, [fetchData]);

    const formatPrice = (amount: number) => {
        return new Intl.NumberFormat('en-IN', {
            style: 'currency',
            currency: 'INR',
            maximumFractionDigits: 0
        }).format(amount);
    };

    const displayPrice = selectedVariant?.price ?? product?.price ?? 0;

    return (
        <section className="pt-6">
            {/* Section header */}
            <div className="mb-10 max-w-2xl">
                <h2 className="text-3xl font-bold text-gray-900 mb-2">Community Experiences</h2>
                <p className="text-[15px] text-gray-500">Stories of restoration and balance from our collective.</p>
            </div>

            {loading ? (
                <div className="space-y-4">
                    {Array.from({ length: 3 }).map((_, i) => (
                        <div key={i} className="h-20 animate-pulse rounded-lg bg-neutral-100" />
                    ))}
                </div>
            ) : (
                <div className="grid gap-10 lg:grid-cols-[1fr_320px] items-stretch">
                    {/* ── Left: Reviews + Form ── */}
                    <div className="flex flex-col">
                        {/* Sort */}
                        {reviews.length > 0 && (
                            <div className="mb-8 flex items-center justify-between">
                                <p className="text-sm font-semibold text-gray-500 uppercase tracking-wider">
                                    {reviews.length} Review{reviews.length !== 1 ? 's' : ''}
                                </p>
                                <select
                                    value={sort}
                                    onChange={e => setSort(e.target.value)}
                                    className="rounded-full border border-gray-200 px-4 py-2 text-sm font-medium text-gray-700 focus:outline-none focus:border-[#1d351d] focus:ring-1 focus:ring-[#1d351d] bg-white cursor-pointer hover:bg-gray-50 transition-colors"
                                >
                                    {SORT_OPTIONS.map(o => (
                                        <option key={o.value} value={o.value}>{o.label}</option>
                                    ))}
                                </select>
                            </div>
                        )}

                        {/* Review list —— flex-1 to push form down */}
                        <div className="flex-1 pb-10">
                            {reviews.length > 0 ? (
                                <div className="space-y-6">
                                    {reviews.map(r => (
                                        <ReviewCard key={r.review_id} review={r} />
                                    ))}
                                </div>
                            ) : (
                                <div className="rounded-xl border border-dashed border-neutral-200 py-12 text-center bg-white h-full flex flex-col justify-center">
                                    <MessageSquare className="mx-auto h-8 w-8 text-neutral-300 mb-2" />
                                    <p className="text-neutral-500 text-sm">No reviews yet. Be the first to share your thoughts!</p>
                                </div>
                            )}
                        </div>

                        {/* Review form —— Bottom-aligned */}
                        <ReviewForm
                            productId={productId}
                            existingReview={myReview ? {
                                rating: myReview.rating,
                                title: myReview.title,
                                body: myReview.body,
                            } : null}
                            onSubmitted={fetchData}
                        />
                    </div>

                    {/* ── Right: Sidebar (Summary + Product Card) ── */}
                    <div className="flex flex-col">
                        <div className="lg:sticky lg:top-24 flex-1 flex flex-col items-stretch">
                            {/* Rating Summary Card (TOP) */}
                            <div className="rounded-xl border border-neutral-200 bg-white p-6 shadow-sm">
                                <div className="text-center">
                                    <p className="text-5xl font-bold text-gray-900 leading-none">
                                        {(summary?.average_rating ?? 0).toFixed(1)}
                                    </p>
                                    <StarRating
                                        value={summary?.average_rating ?? 0}
                                        size="lg"
                                        className="justify-center mt-3"
                                    />
                                    <p className="mt-3 text-sm text-neutral-500 font-medium">
                                        Based on {summary?.total_reviews ?? 0} review{(summary?.total_reviews ?? 0) !== 1 ? 's' : ''}
                                    </p>
                                </div>

                                {/* Star distribution bars */}
                                {summary && summary.total_reviews > 0 && (
                                    <div className="mt-8 space-y-2.5">
                                        {[5, 4, 3, 2, 1].map(star => {
                                            const count = summary.distribution[star] ?? 0;
                                            const pct = (count / (summary.total_reviews || 1)) * 100;
                                            return (
                                                <div key={star} className="flex items-center gap-3 text-sm">
                                                    <span className="w-3 text-right text-gray-500 font-medium">{star}</span>
                                                    <StarRating value={star} size="sm" className="flex-shrink-0" />
                                                    <div className="flex-1 h-1.5 bg-gray-100 rounded-full overflow-hidden">
                                                        <div
                                                            className="h-full rounded-full bg-[#1d351d] transition-all duration-500"
                                                            style={{ width: `${pct}%` }}
                                                        />
                                                    </div>
                                                    <span className="w-8 text-right text-xs font-semibold text-gray-400">{count}</span>
                                                </div>
                                            );
                                        })}
                                    </div>
                                )}
                            </div>

                            {/* Spacing element to push product card to the very bottom */}
                            <div className="flex-1 min-h-[40px]" />

                            {/* ✅ STICKY PRODUCT CARD —— Balanced & Context-Aware */}
                            {product && (
                                <div className="overflow-hidden rounded-xl border border-neutral-200 bg-white shadow-sm transition-all hover:shadow-md">
                                    <div className="p-5">
                                        <div className="aspect-square w-full mb-4 overflow-hidden rounded-lg bg-gray-50 flex items-center justify-center">
                                            <img 
                                                src={product.thumbnail_url || product.images?.[0] || '/placeholder.png'} 
                                                alt={product.product_name}
                                                className="max-h-full max-w-full object-contain p-4 transition-transform hover:scale-110 duration-500"
                                            />
                                        </div>
                                        <h3 className="text-sm font-bold text-gray-900 line-clamp-2 leading-snug mb-2">
                                            {product.product_name}
                                        </h3>
                                        <div className="flex items-baseline gap-2">
                                            <p className="text-base font-bold text-gray-900">
                                                {formatPrice(displayPrice)}
                                            </p>
                                            {selectedVariant?.size_label && (
                                                <p className="text-[10px] text-gray-400 uppercase tracking-wider font-bold">
                                                    / {selectedVariant.size_label}
                                                </p>
                                            )}
                                        </div>
                                    </div>

                                    <div className="px-0 pb-6">
                                        {product.variants?.length > 1 ? (
                                            <button
                                                onClick={() => {
                                                    window.scrollTo({ top: 0, behavior: 'smooth' });
                                                }}
                                                className="w-full bg-[#1d351d] py-3.5 text-[11px] font-bold text-white transition-colors hover:bg-[#152a15] flex items-center justify-center gap-2 uppercase tracking-[0.2em]"
                                            >
                                                <svg viewBox="0 0 24 24" className="w-4 h-4 fill-none stroke-current stroke-2">
                                                    <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z" />
                                                    <circle cx="12" cy="12" r="3" />
                                                </svg>
                                                Preview Options
                                            </button>
                                        ) : (
                                            <button
                                                onClick={onAddToCart}
                                                className="w-full bg-[#1d351d] py-4 text-[11px] font-bold text-white transition-colors hover:bg-[#152a15] flex items-center justify-center gap-2 uppercase tracking-[0.2em]"
                                            >
                                                Add to Bag
                                            </button>
                                        )}
                                    </div>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            )}
        </section>
    );
}

'use client';

import { createPortal } from 'react-dom';
import { useEffect, useState } from 'react';

interface ConfirmModalProps {
    isOpen: boolean;
    title: string;
    message: string;
    confirmText?: string;
    cancelText?: string;
    onConfirm: () => void;
    onCancel: () => void;
    isDestructive?: boolean;
}

export default function ConfirmModal({
    isOpen,
    title,
    message,
    confirmText = 'Confirm',
    cancelText = 'Cancel',
    onConfirm,
    onCancel,
    isDestructive = true,
}: ConfirmModalProps) {
    const [isMounted, setIsMounted] = useState(false);

    useEffect(() => {
        setIsMounted(true);
    }, []);

    // Prevent scrolling when modal is open 
    useEffect(() => {
        if (isOpen) {
            document.body.style.overflow = 'hidden';
        } else {
            document.body.style.overflow = 'unset';
        }

        return () => {
            document.body.style.overflow = 'unset';
        };
    }, [isOpen]);

    if (!isMounted || !isOpen) return null;

    return createPortal(
        <div className="fixed inset-0 z-[9999] flex items-center justify-center p-4 bg-charcoal/50 backdrop-blur-md animate-in fade-in duration-300">
            <div className="bg-white/95 backdrop-blur-sm rounded-2xl shadow-2xl w-full max-w-sm overflow-hidden transform transition-all scale-100 animate-in zoom-in-95 duration-300 border border-white/20">
                <div className="p-6">
                    <h3 className="text-xl font-bold text-[#1A1A1A] mb-2">{title}</h3>
                    <p className="text-[#4A4A4A] text-sm leading-relaxed">{message}</p>
                </div>
                <div className="bg-[#F5F4F0] px-6 py-4 flex items-center justify-end gap-3 rounded-b-xl border-t border-[#E8E4DC]">
                    <button
                        onClick={onCancel}
                        className="px-4 py-2 rounded-lg text-sm font-semibold text-[#4A4A4A] hover:bg-black/5 transition-colors focus:ring-2 focus:ring-[#E8E4DC] focus:outline-none"
                    >
                        {cancelText}
                    </button>
                    <button
                        onClick={onConfirm}
                        className={`px-4 py-2 rounded-lg text-sm font-semibold text-white transition-colors shadow-sm focus:ring-2 focus:ring-offset-1 focus:outline-none ${
                            isDestructive 
                                ? 'bg-[#C0392B] hover:bg-[#A93226] focus:ring-[#C0392B]/50' 
                                : 'bg-[#6B8F5E] hover:bg-[#5A7A4E] focus:ring-[#6B8F5E]/50'
                        }`}
                    >
                        {confirmText}
                    </button>
                </div>
            </div>
        </div>,
        document.body
    );
}

import React from 'react';

interface Block {
    type: 'heading' | 'paragraph';
    text: string;
}

interface LegalContentRendererProps {
    content: string;
}

export default function LegalContentRenderer({ content }: LegalContentRendererProps) {
    if (!content) {
        return <p className="text-gray-500 italic">Content is currently being updated. Please check back later.</p>;
    }

    try {
        const blocks = JSON.parse(content);
        if (Array.isArray(blocks) && blocks.length > 0 && blocks[0].type) {
            return (
                <div className="space-y-8">
                    {blocks.map((block: Block, idx: number) => (
                        <div key={idx}>
                            {block.type === 'heading' ? (
                                <h2 className="text-2xl lg:text-3xl font-bold text-gray-900 mt-12 mb-6 first:mt-0">
                                    {block.text}
                                </h2>
                            ) : (
                                <p className="text-gray-700 text-lg leading-relaxed whitespace-pre-wrap mb-6 last:mb-0 text-left">
                                    {block.text}
                                </p>
                            )}
                        </div>
                    ))}
                </div>
            );
        }
    } catch (e) {
        // Fallback for legacy HTML content
    }

    // Heuristic: If it looks like escaped HTML, unescape the most common tags
    let finalContent = content;
    if (content.includes('&lt;') && !content.includes('<')) {
        finalContent = content
            .replace(/&lt;/g, '<')
            .replace(/&gt;/g, '>')
            .replace(/&quot;/g, '"')
            .replace(/&amp;/g, '&')
            .replace(/&nbsp;/g, ' ');
    }

    return (
        <div 
            className="legal-rich-text max-w-none text-left"
            dangerouslySetInnerHTML={{ __html: finalContent }}
        />
    );
}

