                    <button
                        onClick={onClose}
                        className="px-6 py-2 rounded-xl text-sm font-semibold text-white bg-[#1e3d1e] hover:bg-[#2d5a2d] transition-all shadow-lg shadow-[#1e3d1e]/20 cursor-pointer"
                    >
